t["Fine. %2 it is. Don't wear it out."] = "\\u0637\\u064A\\u0628. %2. \\u0628\\u0633 \\u0644\\u0627 \\u062A\\u0633\\u062A\\u0647\\u0644\\u0643\\u0647."
