t["Finished %1. It changed my mind on one thing. Don't make a fuss."] = "\\u062E\\u0644\\u0635\\u062A %1. \\u063A\\u064A\\u0631 \\u0631\\u0623\\u064A\\u064A \\u0628\\u0634\\u063A\\u0644\\u0629 \\u0648\\u062D\\u062F\\u0629. \\u0644\\u0627 \\u062A\\u0643\\u0628\\u0631\\u0647\\u0627."
