t["Firehouse. Brave folks. Bad luck."] = "\\u0645\\u0631\\u0643\\u0632 \\u0625\\u0637\\u0641\\u0627\\u0621. \\u0646\\u0627\\u0633 \\u0634\\u062C\\u0639\\u0627\\u0646. \\u062D\\u0638 \\u0639\\u0627\\u0637\\u0644."
t["First-aid stock is thin. We should fix that."] = "\\u0639\\u062F\\u0629 \\u0627\\u0644\\u0625\\u0633\\u0639\\u0627\\u0641 \\u0642\\u0644\\u064A\\u0644\\u0629. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u0635\\u0644\\u0651\\u062D \\u0647\\u0627\\u0644\\u0634\\u064A."
t["Fish: present. Fishing rod: absent."] = "\\u0627\\u0644\\u0633\\u0645\\u0643: \\u0645\\u0648\\u062C\\u0648\\u062F. \\u0627\\u0644\\u0635\\u0646\\u0627\\u0631\\u0629: \\u063A\\u0627\\u064A\\u0628\\u0629."
t["Fixed the window. Fixed the door. Fixed nothing that actually matters. Oh well."] = "\\u0635\\u0644\\u0651\\u062D\\u062A \\u0627\\u0644\\u0634\\u0628\\u0627\\u0643. \\u0635\\u0644\\u0651\\u062D\\u062A \\u0627\\u0644\\u0628\\u0627\\u0628. \\u0648\\u0645\\u0627 \\u0635\\u0644\\u0651\\u062D\\u062A \\u0634\\u064A \\u0628\\u064A\\u0647\\u0645 \\u0639\\u0646 \\u062C\\u062F. \\u0645\\u0627\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644."
t["Fixed the window. Fixed the door. Fixed nothing that actually matters. Shit."] = "\\u0635\\u0644\\u0651\\u062D\\u062A \\u0627\\u0644\\u0634\\u0628\\u0627\\u0643. \\u0635\\u0644\\u0651\\u062D\\u062A \\u0627\\u0644\\u0628\\u0627\\u0628. \\u0648\\u0645\\u0627 \\u0635\\u0644\\u0651\\u062D\\u062A \\u0634\\u064A \\u0628\\u064A\\u0647\\u0645 \\u0639\\u0646 \\u062C\\u062F. \\u0632\\u0641\\u062A."
t["Fixin' to end this one!"] = "\\u0647\\u0644\\u0623 \\u0628\\u062E\\u0644\\u0635 \\u0639\\u0644\\u0649 \\u0647\\u0627\\u062F!"
t["Floss daily. Doctor's orders. Doctor's gone, but the order stands."] = "\\u062E\\u064A\\u0637 \\u0627\\u0644\\u0623\\u0633\\u0646\\u0627\\u0646 \\u0643\\u0644 \\u064A\\u0648\\u0645. \\u0623\\u0648\\u0627\\u0645\\u0631 \\u0627\\u0644\\u062F\\u0643\\u062A\\u0648\\u0631. \\u0627\\u0644\\u062F\\u0643\\u062A\\u0648\\u0631 \\u0631\\u0627\\u062D\\u060C \\u0648\\u0627\\u0644\\u0623\\u0645\\u0631 \\u0628\\u0627\\u0642\\u064A."
t["Fog has cut our useful sight range. Tight formation."] = "\\u0627\\u0644\\u0636\\u0628\\u0627\\u0628 \\u0642\\u0635\\u0631 \\u0645\\u062F\\u0649 \\u0646\\u0638\\u0631\\u0646\\u0627. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0644\\u0627\\u0632\\u0642\\u064A\\u0646 \\u0628\\u0628\\u0639\\u0636."
t["Fog like this makes every corner a blind corner."] = "\\u0636\\u0628\\u0627\\u0628 \\u0647\\u064A\\u0643 \\u0628\\u064A\\u062E\\u0644\\u064A \\u0643\\u0644 \\u0632\\u0627\\u0648\\u064A\\u0629 \\u0639\\u0645\\u064A\\u0629."
t["Fog or not, we keep each other in sight."] = "\\u0636\\u0628\\u0627\\u0628 \\u0648\\u0644\\u0627 \\u0645\\u0648 \\u0636\\u0628\\u0627\\u0628\\u060C \\u0645\\u0646\\u0636\\u0644 \\u0634\\u0627\\u064A\\u0641\\u064A\\u0646 \\u0628\\u0639\\u0636."
t["Fog's getting thick. Stay where we can see each other."] = "\\u0627\\u0644\\u0636\\u0628\\u0627\\u0628 \\u0639\\u0645 \\u064A\\u062A\\u0642\\u0644. \\u0636\\u0644\\u0648\\u0627 \\u0648\\u064A\\u0646 \\u0645\\u0646\\u0634\\u0648\\u0641 \\u0628\\u0639\\u0636."
t["Folks round here used to wave at strangers. Now we count them."] = "\\u0627\\u0644\\u0639\\u0627\\u0644\\u0645 \\u0647\\u0648\\u0646 \\u0643\\u0627\\u0646\\u062A \\u062A\\u0633\\u0644\\u0651\\u0645 \\u0639\\u0627\\u0644\\u063A\\u0631\\u064A\\u0628. \\u0647\\u0644\\u0623 \\u0645\\u0646\\u0639\\u062F\\u0651\\u0647\\u0645."
t["Follow the clean floor. Stop when it starts looking occupied."] = "\\u0627\\u0645\\u0634\\u064A \\u0645\\u0639 \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0627\\u0644\\u0646\\u0636\\u064A\\u0641\\u0629. \\u0648\\u0648\\u0642\\u0641 \\u0644\\u0645\\u0627 \\u064A\\u0628\\u064A\\u0646 \\u0625\\u0646\\u0647 \\u0641\\u064A \\u062D\\u062F\\u0627."
t["Food is ready for storage."] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u062C\\u0627\\u0647\\u0632 \\u0644\\u0644\\u062A\\u062E\\u0632\\u064A\\u0646."
t["Food need is rising, but not critical yet."] = "\\u0627\\u0644\\u062D\\u0627\\u062C\\u0629 \\u0644\\u0644\\u0623\\u0643\\u0644 \\u0639\\u0645 \\u062A\\u0632\\u064A\\u062F\\u060C \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0645\\u0648 \\u062E\\u0637\\u0631."
t["Food needs to become a priority."] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0635\\u064A\\u0631 \\u0623\\u0648\\u0644\\u0648\\u064A\\u0629."
t["Food should be on the next short list."] = "\\u0644\\u0627\\u0632\\u0645 \\u0627\\u0644\\u0623\\u0643\\u0644 \\u064A\\u0643\\u0648\\u0646 \\u0639\\u0627\\u0644\\u0642\\u0627\\u064A\\u0645\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["Food soon would be good, if there is enough for everyone."] = "\\u0623\\u0643\\u0644 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B \\u0628\\u064A\\u0643\\u0648\\u0646 \\u0645\\u0646\\u064A\\u062D\\u060C \\u0625\\u0630\\u0627 \\u0628\\u064A\\u0643\\u0641\\u064A \\u0627\\u0644\\u0643\\u0644."
t["Food soon, before it starts costing us attention."] = "\\u0623\\u0643\\u0644 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B\\u060C \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0628\\u0644\\u0651\\u0634 \\u064A\\u0627\\u062E\\u062F \\u0645\\u0646 \\u0627\\u0646\\u062A\\u0628\\u0627\\u0647\\u0646\\u0627."
t["Food would help. I am running on empty."] = "\\u0627\\u0644\\u0623\\u0643\\u0644 \\u0628\\u064A\\u0633\\u0627\\u0639\\u062F. \\u0645\\u0627\\u0634\\u064A\\u0629 \\u0639\\u0627\\u0644\\u0641\\u0627\\u0636\\u064A."
t["Food. Now, please."] = "\\u0623\\u0643\\u0644. \\u0647\\u0644\\u0623\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["Footing's compromised. Relocating."] = "\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0645\\u0648 \\u0645\\u0636\\u0645\\u0648\\u0646\\u0629. \\u0639\\u0645 \\u063A\\u064A\\u0631 \\u0645\\u0637\\u0631\\u062D\\u064A."
t["For God's sake, die!"] = "\\u0628\\u062D\\u064A\\u0627\\u0629 \\u0627\\u0644\\u0644\\u0647, \\u0645\\u0648\\u062A!"
t["For a minute I almost forgot where we are."] = "\\u0644\\u062F\\u0642\\u064A\\u0642\\u0629 \\u0643\\u0646\\u062A \\u0631\\u062D \\u0627\\u0646\\u0633\\u0649 \\u0648\\u064A\\u0646 \\u0646\\u062D\\u0646\\u0627."
t["For a minute, it almost does feel normal."] = "\\u0644\\u062F\\u0642\\u064A\\u0642\\u0629\\u060C \\u0639\\u0646 \\u062C\\u062F \\u0628\\u064A\\u0635\\u064A\\u0631 \\u0639\\u0627\\u062F\\u064A \\u062A\\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["For a moment, it sounded like rain on a safe roof."] = "\\u0644\\u0644\\u062D\\u0638\\u0629\\u060C \\u0643\\u0627\\u0646 \\u0635\\u0648\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u0645\\u0637\\u0631 \\u0639\\u0644\\u0649 \\u0633\\u0642\\u0641 \\u0622\\u0645\\u0646."
t["For a moment, let's be people with a radio again."] = "\\u0644\\u0644\\u062D\\u0638\\u0629\\u060C \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0631\\u062C\\u0639 \\u0646\\u0627\\u0633 \\u0639\\u0646\\u062F\\u0647\\u0627 \\u0631\\u0627\\u062F\\u064A\\u0648."
t["For fuck's sake. Just give me some space."] = "\\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648 \\u0647\\u0627\\u0644\\u0639\\u064A\\u0634\\u0629. \\u0628\\u0633 \\u0641\\u0643 \\u0639\\u0646\\u064A \\u0634\\u0648\\u064A."
t["For now, I want a quiet day and the strength for another."] = "\\u0647\\u0644\\u0623 \\u0628\\u062F\\u064A \\u064A\\u0648\\u0645 \\u0647\\u0627\\u062F\\u064A\\u060C \\u0648\\u0642\\u0648\\u0629 \\u0644\\u064A\\u0648\\u0645 \\u062A\\u0627\\u0646\\u064A."
t["For now, I'm %1."] = "\\u0644\\u0647\\u0644\\u0623 \\u0634\\u063A\\u0644\\u062A\\u064A %1."
t["For now, I'm %1. An uneventful report is a good report."] = "\\u0644\\u0647\\u0644\\u0623 \\u0634\\u063A\\u0644\\u062A\\u064A %1. \\u0627\\u0644\\u062A\\u0642\\u0631\\u064A\\u0631 \\u0627\\u0644\\u0645\\u0645\\u0644 \\u062A\\u0642\\u0631\\u064A\\u0631 \\u0645\\u0646\\u064A\\u062D."
t["For now, pass the tin. Company helps."] = "\\u0647\\u0644\\u0623 \\u0646\\u0627\\u0648\\u0644\\u0646\\u064A \\u0627\\u0644\\u0639\\u0644\\u0628\\u0629. \\u0627\\u0644\\u0635\\u062D\\u0628\\u0629 \\u0628\\u062A\\u0633\\u0627\\u0639\\u062F."
t["For once, I like our chances."] = "\\u0644\\u0645\\u0631\\u0629 \\u0648\\u062D\\u062F\\u0629\\u060C \\u062D\\u0638\\u0648\\u0638\\u0646\\u0627 \\u0639\\u0627\\u062C\\u0628\\u062A\\u0646\\u064A."
t["For once, everything feels manageable."] = "\\u0644\\u0645\\u0631\\u0629 \\u0648\\u062D\\u062F\\u0629\\u060C \\u0643\\u0644\\u0634\\u064A \\u062D\\u0627\\u0633\\u062A\\u0647 \\u0645\\u0645\\u0643\\u0646."
t["For pity's sake. Just give me some space."] = "\\u064A\\u0627 \\u0627\\u0644\\u0644\\u0647. \\u0628\\u0633 \\u0641\\u0643 \\u0639\\u0646\\u064A \\u0634\\u0648\\u064A."
t["Forty years in oak. Shame to drink it now. Shame not to."] = "\\u0623\\u0631\\u0628\\u0639\\u064A\\u0646 \\u0633\\u0646\\u0629 \\u0628\\u0627\\u0644\\u0628\\u0644\\u0648\\u0637. \\u062D\\u0631\\u0627\\u0645 \\u064A\\u0646\\u0634\\u0631\\u0628 \\u0647\\u0644\\u0623. \\u0648\\u062D\\u0631\\u0627\\u0645 \\u0645\\u0627 \\u064A\\u0646\\u0634\\u0631\\u0628."
t["Found %1 on the shelf. I'll bring it back when I'm done."] = "\\u0644\\u0642\\u064A\\u062A %1 \\u0639\\u0627\\u0644\\u0631\\u0641. \\u0628\\u0631\\u062C\\u0639\\u0647 \\u0644\\u0645\\u0627 \\u062E\\u0644\\u0635."
t["Found %1. At least this trip gave us something."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u062C\\u0627\\u0628 \\u0634\\u064A."
t["Found %1. Back to the list, I suppose."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0646\\u0631\\u062C\\u0639 \\u0639\\u0627\\u0644\\u0644\\u064A\\u0633\\u062A\\u0629, \\u0634\\u0643\\u0644\\u0647."
t["Found %1. Bag it separately. Very separately."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u0643\\u064A\\u0633 \\u0644\\u062D\\u0627\\u0644. \\u0644\\u062D\\u0627\\u0644 \\u0643\\u062A\\u064A\\u0631."
t["Found %1. Disgusting doesn't mean defeated."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0645\\u0642\\u0631\\u0641, \\u0628\\u0633 \\u0645\\u0627 \\u063A\\u0644\\u0628\\u0646\\u064A."
t["Found %1. Don't touch it bare-handed like I just did."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0644\\u0627 \\u062A\\u0644\\u0645\\u0633\\u0647 \\u0628\\u0625\\u064A\\u062F\\u0643 \\u0645\\u062A\\u0644\\u064A."
t["Found %1. Even the dead wouldn't steal this."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u062D\\u062A\\u0649 \\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u064A\\u0633\\u0631\\u0642\\u0648\\u0627 \\u0647\\u0627\\u0644\\u0634\\u064A."
t["Found %1. Finally, something that isn't trying to kill us."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0623\\u062E\\u064A\\u0631\\u0627 \\u0634\\u064A \\u0645\\u0627 \\u0628\\u062F\\u0647 \\u064A\\u0642\\u062A\\u0644\\u0646\\u0627."
t["Found %1. Fine. Not good. Fine."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0645\\u0627\\u0634\\u064A. \\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D. \\u0628\\u0633 \\u0645\\u0627\\u0634\\u064A."
t["Found %1. Good return for the time."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0627\\u0644\\u0648\\u0642\\u062A \\u0645\\u0627 \\u0631\\u0627\\u062D \\u0639\\u0627\\u0644\\u0641\\u0627\\u0636\\u064A."
t["Found %1. Good. That makes the next bad surprise easier."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0645\\u0646\\u064A\\u062D. \\u0647\\u064A\\u0643 \\u0627\\u0644\\u0645\\u0635\\u064A\\u0628\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u062A\\u0647\\u0648\\u0646."
t["Found %1. Hygiene cost: unacceptable."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0627\\u0644\\u0636\\u0631\\u064A\\u0628\\u0629 \\u0639\\u0627\\u0644\\u0646\\u0636\\u0627\\u0641\\u0629: \\u0645\\u0627 \\u0628\\u062A\\u0646\\u0642\\u0628\\u0644."
t["Found %1. I am washing twice when we get home."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0631\\u062D \\u0627\\u062A\\u063A\\u0633\\u0644 \\u0645\\u0631\\u062A\\u064A\\u0646 \\u0644\\u0645\\u0627 \\u0646\\u0631\\u062C\\u0639."
t["Found %1. I can hold my breath longer than it can stink."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0646\\u0641\\u0633\\u064A \\u0623\\u0637\\u0648\\u0644 \\u0645\\u0646 \\u0631\\u064A\\u062D\\u062A\\u0647."
t["Found %1. I expected nothing and somehow got less."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u062A \\u0634\\u064A, \\u0648\\u0637\\u0644\\u0639 \\u0623\\u0642\\u0644."
t["Found %1. I miss clean shelves."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0627\\u0634\\u062A\\u0642\\u062A \\u0644\\u0644\\u0631\\u0641\\u0648\\u0641 \\u0627\\u0644\\u0646\\u0636\\u064A\\u0641\\u0629."
t["Found %1. I need a different pair of gloves."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u062F\\u064A \\u0643\\u0641\\u0648\\u0641 \\u063A\\u064A\\u0631 \\u0647\\u062F\\u0648\\u0644."
t["Found %1. I need one useful thing today."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u062F\\u064A \\u0634\\u064A \\u0648\\u0627\\u062D\\u062F \\u0645\\u0641\\u064A\\u062F \\u0627\\u0644\\u064A\\u0648\\u0645."
t["Found %1. I want it out of my hands right now."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u062F\\u064A \\u064A\\u0627\\u0647 \\u064A\\u0637\\u0644\\u0639 \\u0645\\u0646 \\u0625\\u064A\\u062F\\u064A \\u0647\\u0644\\u0623."
t["Found %1. I'll file it under bad timing."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u0633\\u062C\\u0644 \\u0647\\u0627\\u0644\\u0634\\u064A \\u062A\\u062D\\u062A \\u0628\\u0646\\u062F \\u0627\\u0644\\u062A\\u0648\\u0642\\u064A\\u062A \\u0627\\u0644\\u0632\\u0641\\u062A."
t["Found %1. I'll try the next place."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u062C\\u0631\\u0628 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0628\\u0639\\u062F\\u0647."
t["Found %1. I'll wash the smell off eventually."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0627\\u0644\\u0631\\u064A\\u062D\\u0629 \\u0631\\u062D \\u062A\\u0631\\u0648\\u062D \\u0628\\u064A\\u0648\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0623\\u064A\\u0627\\u0645."
t["Found %1. I'm keeping it outside the pack."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0631\\u062D \\u062E\\u0644\\u064A\\u0647 \\u0628\\u0631\\u0627 \\u0627\\u0644\\u0634\\u0646\\u062A\\u0629."
t["Found %1. I'm still checking the next room."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0644\\u0633\\u0627 \\u0631\\u062D \\u0634\\u0648\\u0641 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["Found %1. It has been a difficult day for soap."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0627\\u0644\\u064A\\u0648\\u0645 \\u064A\\u0648\\u0645 \\u0635\\u0639\\u0628 \\u0639\\u0627\\u0644\\u0635\\u0627\\u0628\\u0648\\u0646."
t["Found %1. Keep it away from the food."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u0639\\u062F\\u0647 \\u0639\\u0646 \\u0627\\u0644\\u0623\\u0643\\u0644."
t["Found %1. Let the dead complain about it."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u062E\\u0644\\u064A \\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u064A\\u0634\\u062A\\u0643\\u0648\\u0627."
t["Found %1. Let's leave before the noise catches up."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0641\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0644\\u062D\\u0642\\u0646\\u0627 \\u0627\\u0644\\u0635\\u0648\\u062A."
t["Found %1. Low priority; keep searching."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0645\\u0648 \\u0623\\u0648\\u0644\\u0648\\u064A\\u0629, \\u0643\\u0645\\u0644 \\u062F\\u0648\\u0631."
t["Found %1. Maybe I can repair it for someone."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u064A\\u0645\\u0643\\u0646 \\u0628\\u0635\\u0644\\u062D\\u0647 \\u0644\\u062D\\u062F\\u0627."
t["Found %1. Maybe our luck finally changed."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u064A\\u0645\\u0643\\u0646 \\u0623\\u062E\\u064A\\u0631\\u0627 \\u0627\\u062A\\u063A\\u064A\\u0631 \\u062D\\u0638\\u0646\\u0627."
t["Found %1. Maybe someone can still make use of it."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u064A\\u0645\\u0643\\u0646 \\u062D\\u062F\\u0627 \\u0644\\u0633\\u0627 \\u064A\\u0633\\u062A\\u0641\\u064A\\u062F \\u0645\\u0646\\u0647."
t["Found %1. Maybe that'll make somebody's day easier."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u064A\\u0645\\u0643\\u0646 \\u064A\\u0647\\u0648\\u0646 \\u064A\\u0648\\u0645 \\u062D\\u062F\\u0627 \\u0634\\u0648\\u064A."
