t["Give me a moment. I'm %1."] = "\\u0639\\u0637\\u064A\\u0646\\u064A \\u0644\\u062D\\u0638\\u0629. \\u0645\\u0634\\u063A\\u0648\\u0644\\u0629 \\u0628\\u0640%1."
