t["Give me a quiet place to sit."] = "\\u0644\\u0642\\u064A\\u0644\\u064A \\u0645\\u0637\\u0631\\u062D \\u0647\\u0627\\u062F\\u064A \\u0627\\u0642\\u0639\\u062F \\u0641\\u064A\\u0647."
t["Give me a shovel and I'll finish the argument."] = "\\u0639\\u0637\\u064A\\u0646\\u064A \\u0643\\u0631\\u064A\\u0643 \\u0648\\u0628\\u0646\\u0647\\u064A \\u0627\\u0644\\u0646\\u0642\\u0627\\u0634."
t["Give me an exit and I'll go. Not before."] = "\\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0645\\u062E\\u0631\\u062C \\u0648\\u0628\\u0631\\u0648\\u062D. \\u0645\\u0648 \\u0642\\u0628\\u0644."
t["Give me one breath and I'll be dangerous again."] = "\\u0639\\u0637\\u064A\\u0646\\u064A \\u0646\\u0641\\u0633 \\u0648\\u0627\\u062D\\u062F \\u0648\\u0628\\u0631\\u062C\\u0639 \\u062E\\u0637\\u064A\\u0631\\u0629."
t["Give me one opening, %1!"] = "\\u0639\\u0637\\u064A\\u0646\\u064A \\u0641\\u062A\\u062D\\u0629 \\u0648\\u062D\\u062F\\u0629 \\u064A\\u0627 %1!"
t["Give me room. I'm not losing you to this."] = "\\u0648\\u0633\\u0651\\u0639\\u0644\\u064A. \\u0645\\u0627 \\u0631\\u062D \\u062E\\u0633\\u0631\\u0643 \\u0628\\u0633\\u0628\\u0628 \\u0647\\u0627\\u062F."
t["Give me something with an edge, then ask again."] = "\\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0634\\u064A \\u0625\\u0644\\u0647 \\u062D\\u062F\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0627\\u0633\\u0623\\u0644."
t["Give me space to go over what happened."] = "\\u0639\\u0637\\u064A\\u0646\\u064A \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0631\\u0627\\u062C\\u0639 \\u0641\\u064A\\u0647\\u0627 \\u0627\\u0644\\u0644\\u064A \\u0635\\u0627\\u0631."
t["Give me the book after you. I'll find my own fight with it."] = "\\u0639\\u0637\\u064A\\u0646\\u064A \\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0628\\u0639\\u062F\\u0643. \\u0631\\u062D \\u0644\\u0627\\u0642\\u064A \\u062E\\u0646\\u0627\\u0642\\u062A\\u064A \\u0627\\u0644\\u062E\\u0627\\u0635\\u0629 \\u0645\\u0639\\u0647."
t["Give me the ground and a tool. I'll make it useful."] = "\\u0639\\u0637\\u064A\\u0646\\u064A \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0648\\u0639\\u062F\\u0629\\u060C \\u0648\\u0623\\u0646\\u0627 \\u0628\\u062E\\u0644\\u064A\\u0647\\u0627 \\u062A\\u0646\\u0641\\u0639."
t["Give the body room. I can find another patch."] = "\\u062E\\u0644\\u064A \\u0627\\u0644\\u062C\\u062B\\u0629 \\u0628\\u062D\\u0627\\u0644\\u0647\\u0627. \\u0628\\u0644\\u0627\\u0642\\u064A \\u0645\\u062D\\u0644 \\u062A\\u0627\\u0646\\u064A."
t["Give them a quiet room and a little dignity."] = "\\u0627\\u0639\\u0637\\u0648\\u0647\\u0646 \\u063A\\u0631\\u0641\\u0629 \\u0647\\u0627\\u062F\\u064A\\u0629 \\u0648\\u0634\\u0648\\u064A\\u0629 \\u0643\\u0631\\u0627\\u0645\\u0629."
t["Give this one space!"] = "\\u062E\\u0644\\u064A \\u0645\\u0633\\u0627\\u0641\\u0629 \\u0645\\u0646 \\u0647\\u0627\\u062F!"
t["Glass or timber, it means an entrance just got easier."] = "\\u0642\\u0632\\u0627\\u0632 \\u0623\\u0648 \\u062E\\u0634\\u0628\\u060C \\u064A\\u0639\\u0646\\u064A \\u0641\\u064A \\u0645\\u062F\\u062E\\u0644 \\u0635\\u0627\\u0631 \\u0623\\u0633\\u0647\\u0644."
t["Go on. Say what you came to say."] = "\\u064A\\u0644\\u0627. \\u0642\\u0648\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0627\\u062C\\u064A\\u062A \\u062A\\u0642\\u0648\\u0644\\u0647."
t["Go through the stores again. We are missing something."] = "\\u0631\\u062C\\u0639 \\u0642\\u0644\\u0651\\u0628 \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629. \\u0641\\u064A \\u0634\\u064A \\u0646\\u0627\\u0642\\u0635."
t["Go. Please make losing me mean something."] = "\\u0631\\u0648\\u062D. \\u062E\\u0644\\u064A \\u062E\\u0633\\u0627\\u0631\\u062A\\u064A \\u0625\\u0644\\u0647\\u0627 \\u0645\\u0639\\u0646\\u0649."
t["Goddamn, that's grim. Say another one."] = "\\u064A\\u0644\\u0639\\u0646 \\u0623\\u0628\\u0648\\u0647\\u0627\\u060C \\u0634\\u0648 \\u0633\\u0648\\u062F\\u0627. \\u0642\\u0648\\u0644 \\u0648\\u062D\\u062F\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["Going in empty-handed only gives you someone else to save."] = "\\u0625\\u0630\\u0627 \\u0641\\u062A\\u062A \\u0628\\u0625\\u064A\\u062F\\u064A \\u0641\\u0627\\u0636\\u064A\\u0629\\u060C \\u0628\\u0633 \\u0628\\u062A\\u0635\\u064A\\u0631 \\u0639\\u0646\\u062F\\u0643 \\u062D\\u062F\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u062A\\u0646\\u0642\\u0630\\u0647."
t["Gold stars in a drawer. We could use one for attendance."] = "\\u0646\\u062C\\u0648\\u0645 \\u062F\\u0647\\u0628\\u064A\\u0629 \\u0628\\u0627\\u0644\\u062C\\u0627\\u0631\\u0648\\u0631. \\u0645\\u0646\\u062D\\u062A\\u0627\\u062C \\u0648\\u062D\\u062F\\u0629 \\u0644\\u0644\\u062F\\u0648\\u0627\\u0645."
t["Gone. Dinner has declined to attend."] = "\\u0631\\u0627\\u062D\\u062A. \\u0627\\u0644\\u0639\\u0634\\u0627 \\u0627\\u0639\\u062A\\u0630\\u0631 \\u0639\\u0646 \\u0627\\u0644\\u062D\\u0636\\u0648\\u0631."
t["Good catch. I will keep it cool until we get home."] = "\\u0635\\u064A\\u062F\\u0629 \\u062D\\u0644\\u0648\\u0629. \\u0628\\u062E\\u0644\\u064A\\u0647\\u0627 \\u0628\\u0627\\u0631\\u062F\\u0629 \\u0644\\u0646\\u0648\\u0635\\u0644 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
t["Good conditions, useful plan, no wasted motion."] = "\\u0638\\u0631\\u0648\\u0641 \\u0645\\u0646\\u064A\\u062D\\u0629\\u060C \\u062E\\u0637\\u0629 \\u062A\\u0646\\u0641\\u0639\\u060C \\u0648\\u0628\\u0644\\u0627 \\u062D\\u0631\\u0643\\u0629 \\u0639\\u0627\\u0644\\u0641\\u0627\\u0636\\u064A."
t["Good discipline got us here. Let's maintain it."] = "\\u0627\\u0644\\u0627\\u0646\\u0636\\u0628\\u0627\\u0637 \\u0648\\u0635\\u0651\\u0644\\u0646\\u0627 \\u0644\\u0647\\u0648\\u0646. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0627\\u0641\\u0638 \\u0639\\u0644\\u064A\\u0647."
t["Good explanation. I can use that tomorrow."] = "\\u0634\\u0631\\u062D \\u0645\\u0646\\u064A\\u062D. \\u0628\\u0633\\u062A\\u0641\\u064A\\u062F \\u0645\\u0646\\u0647 \\u0628\\u0643\\u0631\\u0627."
t["Good grief. Where do you even get these?"] = "\\u064A\\u0627 \\u0644\\u0637\\u064A\\u0641. \\u0645\\u0646 \\u0648\\u064A\\u0646 \\u0628\\u062A\\u062C\\u064A\\u0628 \\u0647\\u0627\\u0644\\u062D\\u0643\\u064A\\u061F"
t["Good harvest. We earned this one."] = "\\u0645\\u0648\\u0633\\u0645 \\u0645\\u0646\\u064A\\u062D. \\u062A\\u0639\\u0628\\u0646\\u0627 \\u0639\\u0644\\u064A\\u0647 \\u0648\\u0628\\u0646\\u0633\\u062A\\u0627\\u0647\\u0644\\u0647."
t["Good morning. I'm glad you're still here."] = "\\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631. \\u0645\\u0628\\u0633\\u0648\\u0637\\u0629 \\u0625\\u0646\\u0643 \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646."
t["Good news: no more traffic. Bad news: every other goddamn thing."] = "\\u0627\\u0644\\u062E\\u0628\\u0631 \\u0627\\u0644\\u062D\\u0644\\u0648: \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A \\u0632\\u062D\\u0645\\u0629. \\u0627\\u0644\\u062E\\u0628\\u0631 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0644: \\u0643\\u0644 \\u0634\\u064A \\u062A\\u0627\\u0646\\u064A \\u064A\\u0644\\u0639\\u0646\\u0647."
t["Good news: no more traffic. Bad news: everything else."] = "\\u0627\\u0644\\u062E\\u0628\\u0631 \\u0627\\u0644\\u062D\\u0644\\u0648: \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A \\u0632\\u062D\\u0645\\u0629. \\u0627\\u0644\\u062E\\u0628\\u0631 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0644: \\u0643\\u0644 \\u0634\\u064A \\u062A\\u0627\\u0646\\u064A."
t["Good pull. Back to it."] = "\\u0633\\u062D\\u0628\\u0629 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u064A\\u0644\\u0627 \\u0646\\u0643\\u0645\\u0644."
t["Good stores and clear exits. That is how we keep this."] = "\\u0645\\u0648\\u0646\\u0629 \\u0645\\u0646\\u064A\\u062D\\u0629 \\u0648\\u0645\\u062E\\u0627\\u0631\\u062C \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0647\\u064A\\u0643 \\u0645\\u0646\\u062D\\u0627\\u0641\\u0638 \\u0639\\u0644\\u064A\\u0647."
