t["Good to meet you, %1. I can handle myself."] = "\\u062A\\u0634\\u0631\\u0641\\u0646\\u0627 \\u064A\\u0627 %1. \\u0628\\u0639\\u0631\\u0641 \\u062F\\u0628\\u0631 \\u062D\\u0627\\u0644\\u064A."
t["Good to meet you, %1. I do not want trouble either."] = "\\u062A\\u0634\\u0631\\u0641\\u0646\\u0627 \\u064A\\u0627 %1. \\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0645\\u0634\\u0627\\u0643\\u0644."
t["Good to meet you. Let us both keep this calm."] = "\\u062A\\u0634\\u0631\\u0641\\u0646\\u0627. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0646\\u0627 \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646 \\u0646\\u0636\\u0644 \\u0647\\u0627\\u062F\\u064A\\u064A\\u0646."
t["Good to see a face that isn't trying to bite me."] = "\\u062D\\u0644\\u0648 \\u0627\\u0634\\u0648\\u0641 \\u0648\\u062C\\u0647 \\u0645\\u0627 \\u0628\\u062F\\u0648 \\u064A\\u0639\\u0636\\u0646\\u064A."
t["Good to see a familiar face."] = "\\u062D\\u0644\\u0648 \\u0634\\u0648\\u0641 \\u0648\\u062C\\u0647 \\u0628\\u0639\\u0631\\u0641\\u0647."
t["Good to see you. What are we dealing with today?"] = "\\u062D\\u0644\\u0648 \\u0634\\u0648\\u0641\\u0643. \\u0634\\u0648 \\u0639\\u0646\\u0627 \\u0627\\u0644\\u064A\\u0648\\u0645\\u061F"
