t["Good. A face I don't have to work out again."] = "\\u0645\\u0646\\u064A\\u062D. \\u0648\\u062C\\u0647 \\u0645\\u0648 \\u0645\\u0636\\u0637\\u0631\\u0629 \\u0623\\u062D\\u0632\\u0631\\u0647 \\u0645\\u0646 \\u062C\\u062F\\u064A\\u062F."
t["Good. I was tired of facing them empty-handed."] = "\\u0645\\u0646\\u064A\\u062D. \\u062A\\u0639\\u0628\\u062A \\u0648\\u0627\\u062C\\u0647\\u0646 \\u0628\\u0625\\u064A\\u062F \\u0641\\u0627\\u0636\\u064A\\u0629."
t["Good. I will get my gear ready."] = "\\u0645\\u0646\\u064A\\u062D. \\u0631\\u062D \\u062C\\u0647\\u0632 \\u0639\\u062F\\u062A\\u064A."
t["Good. I'm glad you took it."] = "\\u0645\\u0646\\u064A\\u062D. \\u0645\\u0628\\u0633\\u0648\\u0637\\u0629 \\u0625\\u0646\\u0643 \\u0627\\u062E\\u062F\\u062A\\u0647."
t["Good. Just don't let it slip through the cracks."] = "\\u0645\\u0646\\u064A\\u062D. \\u0628\\u0633 \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0627 \\u062A\\u0636\\u064A\\u0639 \\u0645\\u0646\\u0643."
t["Good. Nobody has to carry the whole place alone."] = "\\u0645\\u0646\\u064A\\u062D. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u062D\\u0645\\u0644 \\u0627\\u0644\\u0628\\u064A\\u062A \\u0643\\u0644\\u0647 \\u0644\\u062D\\u0627\\u0644\\u0647."
t["Good. Nobody has to go hungry tonight."] = "\\u0645\\u0646\\u064A\\u062D. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u0646\\u0627\\u0645 \\u062C\\u0648\\u0639\\u0627\\u0646 \\u0627\\u0644\\u0644\\u064A\\u0644\\u0629."
