t["Good. That is one less thing to learn by mistake."] = "\\u0645\\u0646\\u064A\\u062D. \\u0634\\u063A\\u0644\\u0629 \\u0623\\u0642\\u0644 \\u0646\\u062A\\u0639\\u0644\\u0645\\u0647\\u0627 \\u0628\\u0627\\u0644\\u063A\\u0644\\u0637."
t["Good. We'll write down who gets it first."] = "\\u0645\\u0646\\u064A\\u062D. \\u0645\\u0646\\u0643\\u062A\\u0628 \\u0645\\u064A\\u0646 \\u0628\\u064A\\u0627\\u062E\\u062F\\u0647\\u0627 \\u0623\\u0648\\u0644."
t["Gosh, that's grim. Say another one."] = "\\u064A\\u0627 \\u0627\\u0644\\u0644\\u0647\\u060C \\u0634\\u0648 \\u0633\\u0648\\u062F\\u0627. \\u0642\\u0648\\u0644 \\u0648\\u062D\\u062F\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["Got %1! Heck yes."] = "\\u0644\\u0642\\u064A\\u062A %1! \\u064A\\u0627 \\u0633\\u0644\\u0627\\u0645!"
t["Got %1! Hell yes."] = "\\u0644\\u0642\\u064A\\u062A %1! \\u0625\\u064A \\u0648\\u0627\\u0644\\u0644\\u0647!"
t["Got %1. I need soap, fire, then more soap."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0628\\u062F\\u064A \\u0635\\u0627\\u0628\\u0648\\u0646, \\u0646\\u0627\\u0631, \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0635\\u0627\\u0628\\u0648\\u0646 \\u0643\\u0645\\u0627\\u0646."
t["Got %1. Let's secure it before we press our luck."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0623\\u0645\\u0646 \\u0647\\u0627\\u0644\\u0634\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u062C\\u0631\\u0628 \\u062D\\u0638\\u0646\\u0627 \\u0632\\u064A\\u0627\\u062F\\u0629."
t["Got a lure I can put on this line?"] = "\\u0645\\u0639\\u0643 \\u0637\\u0639\\u0645 \\u0635\\u0646\\u0627\\u0639\\u064A \\u0631\\u0643\\u0628\\u0647 \\u0639\\u0627\\u0644\\u062E\\u064A\\u0637\\u061F"
t["Got a spare rod? The water looks worth a try."] = "\\u0645\\u0639\\u0643 \\u0635\\u0646\\u0627\\u0631\\u0629 \\u0632\\u064A\\u0627\\u062F\\u0629\\u061F \\u0627\\u0644\\u0645\\u064A \\u0634\\u0643\\u0644\\u0647\\u0627 \\u0628\\u062A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u062A\\u062C\\u0631\\u0628\\u0629."
t["Got an axe tucked away somewhere? I could use it now."] = "\\u0641\\u064A \\u0639\\u0646\\u062F\\u0643 \\u0641\\u0627\\u0633 \\u0645\\u062E\\u0628\\u0651\\u0649 \\u0634\\u064A \\u0645\\u062D\\u0644\\u061F \\u0628\\u0644\\u0632\\u0645\\u0646\\u064A \\u0647\\u0644\\u0623."
t["Got it!"] = "\\u062C\\u0628\\u062A\\u0647!"
t["Got it. That will make a meal."] = "\\u0645\\u0633\\u0643\\u062A\\u0647\\u0627. \\u0647\\u064A \\u0628\\u062A\\u0637\\u0644\\u0639 \\u0623\\u0643\\u0644\\u0629."
t["Got my hands back. They were on leave without asking."] = "\\u0631\\u062C\\u0639\\u0648\\u0644\\u064A \\u0625\\u064A\\u062F\\u064A\\u064A. \\u0643\\u0627\\u0646\\u0648\\u0627 \\u0628\\u0625\\u062C\\u0627\\u0632\\u0629 \\u0628\\u0644\\u0627 \\u0625\\u0630\\u0646."
t["Got one good step left. I'm spending it on retreat."] = "\\u0636\\u0644\\u0651\\u062A \\u0645\\u0639\\u064A \\u062E\\u0637\\u0648\\u0629 \\u0645\\u0646\\u064A\\u062D\\u0629 \\u0648\\u062D\\u062F\\u0629. \\u0631\\u062D \\u0627\\u0635\\u0631\\u0641\\u0647\\u0627 \\u0639\\u0627\\u0644\\u0647\\u0631\\u0648\\u0628."
t["Grab the cheap stuff. The good stuff makes you brave."] = "\\u062E\\u0648\\u062F \\u0627\\u0644\\u0631\\u062E\\u064A\\u0635. \\u0627\\u0644\\u063A\\u0627\\u0644\\u064A \\u0628\\u064A\\u062E\\u0644\\u064A\\u0643 \\u062A\\u062A\\u0634\\u062C\\u0639."
t["Gravity still works. Good to know some rules held."] = "\\u0627\\u0644\\u062C\\u0627\\u0630\\u0628\\u064A\\u0629 \\u0644\\u0633\\u0627 \\u0634\\u063A\\u0627\\u0644\\u0629. \\u0645\\u0646\\u064A\\u062D \\u0641\\u064A \\u0642\\u0648\\u0627\\u0646\\u064A\\u0646 \\u0635\\u0645\\u062F\\u062A."
t["Gray sky, empty pumps. Feels like a fine day to be disappointed."] = "\\u0633\\u0645\\u0627 \\u0631\\u0645\\u0627\\u062F\\u064A\\u0629 \\u0648\\u0643\\u0627\\u0632\\u064A\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u064A\\u0648\\u0645 \\u0645\\u0645\\u062A\\u0627\\u0632 \\u0644\\u062E\\u064A\\u0628\\u0629 \\u0627\\u0644\\u0623\\u0645\\u0644."
t["Grey sky, grey road, grey everything. At least it matches."] = "\\u0633\\u0645\\u0627 \\u0631\\u0645\\u0627\\u062F\\u064A\\u0629\\u060C \\u0637\\u0631\\u064A\\u0642 \\u0631\\u0645\\u0627\\u062F\\u064A\\u060C \\u0643\\u0644 \\u0634\\u064A \\u0631\\u0645\\u0627\\u062F\\u064A. \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u0645\\u062A\\u0646\\u0627\\u0633\\u0642\\u064A\\u0646."
t["Grip steady. Breathing controlled. Ready to continue."] = "\\u0627\\u0644\\u0645\\u0633\\u0643\\u0629 \\u062B\\u0627\\u0628\\u062A\\u0629. \\u0627\\u0644\\u0646\\u0641\\u0633 \\u0645\\u0636\\u0628\\u0648\\u0637. \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0643\\u0645\\u0644."
t["Ground first. Ambition later."] = "\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0623\\u0648\\u0644. \\u0627\\u0644\\u0623\\u062D\\u0644\\u0627\\u0645 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["Group ahead. Hit one and keep moving!"] = "\\u062C\\u0645\\u0627\\u0639\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u0627\\u0636\\u0631\\u0628 \\u0648\\u0627\\u062D\\u062F \\u0648\\u0636\\u0644 \\u0645\\u0627\\u0634\\u064A!"
t["Group of zombies in front of us."] = "\\u0641\\u064A \\u062C\\u0645\\u0627\\u0639\\u0629 \\u0632\\u0648\\u0645\\u0628\\u064A \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627."
t["Grow strong or die trying. I understand that."] = "\\u064A\\u0627 \\u0628\\u062A\\u0637\\u0644\\u0639\\u0648\\u0627 \\u0623\\u0642\\u0648\\u064A\\u0627\\u0621 \\u064A\\u0627 \\u0628\\u062A\\u0645\\u0648\\u062A\\u0648\\u0627 \\u0648\\u0623\\u0646\\u062A\\u0648 \\u0639\\u0645 \\u062A\\u062D\\u0627\\u0648\\u0644\\u0648\\u0627. \\u0628\\u0641\\u0647\\u0645\\u0643\\u0646."
t["Guess the staff went home early. Then came back."] = "\\u0634\\u0643\\u0644\\u0647\\u0627 \\u0627\\u0644\\u0643\\u0627\\u062F\\u0631 \\u0631\\u0648\\u0651\\u062D \\u0628\\u0643\\u064A\\u0631. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0631\\u062C\\u0639."
t["Gun's dry. This isn't the time to bluff."] = "\\u0627\\u0644\\u0628\\u0627\\u0631\\u0648\\u062F\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0645\\u0648 \\u0648\\u0642\\u062A \\u0646\\u0641\\u0634 \\u0631\\u064A\\u0634."
t["HEY! Check your target!"] = "\\u0648\\u0644\\u0643! \\u0634\\u0648\\u0641 \\u0645\\u064A\\u0646 \\u0639\\u0645 \\u062A\\u0636\\u0631\\u0628!"
t["HEY! Come chew on someone with worse manners!"] = "\\u0647\\u064A! \\u062A\\u0639\\u0627\\u0644\\u0648\\u0627 \\u0639\\u0636\\u0648\\u0627 \\u062D\\u062F\\u0627 \\u0642\\u0644\\u064A\\u0644 \\u0623\\u062F\\u0628 \\u0623\\u0643\\u062A\\u0631!"
t["HEY! Follow me! Nice clear path this way!"] = "\\u0647\\u064A! \\u0627\\u0644\\u062D\\u0642\\u0646\\u064A! \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0646\\u0636\\u064A\\u0641 \\u0645\\u0646 \\u0647\\u0648\\u0646!"
t["HEY! I already warned you!"] = "\\u0648\\u0644\\u0643! \\u062D\\u0630\\u0631\\u062A\\u0643 \\u0642\\u0628\\u0644 \\u0647\\u064A\\u0643!"
t["HEY! Moving target! This direction!"] = "\\u0647\\u064A! \\u0647\\u062F\\u0641 \\u0645\\u062A\\u062D\\u0631\\u0643! \\u0645\\u0646 \\u0647\\u0648\\u0646!"
t["HEY! One more and I hit back!"] = "\\u0648\\u0644\\u0643! \\u0643\\u0645\\u0627\\u0646 \\u0648\\u062D\\u062F\\u0629 \\u0648\\u0628\\u0631\\u062F \\u0627\\u0644\\u0636\\u0631\\u0628\\u0629!"
t["HEY, UGLY! Over here! I taste better!"] = "\\u064A\\u0627 \\u0628\\u0634\\u0639! \\u0644\\u0647\\u0648\\u0646! \\u0637\\u0639\\u0645\\u062A\\u064A \\u0623\\u0637\\u064A\\u0628!"
t["Ha! %1. Now that's a find."] = "\\u0647\\u0627! %1. \\u0647\\u0627\\u064A \\u0644\\u0642\\u064A\\u0629 \\u0639\\u0646 \\u062C\\u062F."
t["Ha! Fence never stood a chance."] = "\\u0647\\u0627! \\u0627\\u0644\\u0633\\u0648\\u0631 \\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0625\\u0644\\u0647 \\u0623\\u0645\\u0644."
t["Ha! Not today. Thanks."] = "\\u0647\\u0627! \\u0645\\u0648 \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0634\\u0643\\u0631\\u0627."
t["Ha! Off me!"] = "\\u0647\\u0627! \\u0628\\u0639\\u064A\\u062F \\u0639\\u0646\\u064A!"
t["Ha. Hell, I'd do it. Don't let me do it."] = "\\u0647\\u0627. \\u0625\\u064A \\u0648\\u0627\\u0644\\u0644\\u0647 \\u0628\\u0639\\u0645\\u0644\\u0647\\u0627\\u060C \\u064A\\u0644\\u0639\\u0646 \\u0627\\u0644\\u0634\\u064A\\u0637\\u0627\\u0646. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0623\\u0639\\u0645\\u0644\\u0647\\u0627."
t["Ha. I'd do it. Don't let me do it."] = "\\u0647\\u0627. \\u0628\\u0639\\u0645\\u0644\\u0647\\u0627. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0623\\u0639\\u0645\\u0644\\u0647\\u0627."
t["Had a strange thought. It was polite. It left."] = "\\u062C\\u062A\\u0646\\u064A \\u0641\\u0643\\u0631\\u0629 \\u063A\\u0631\\u064A\\u0628\\u0629. \\u0643\\u0627\\u0646\\u062A \\u0645\\u0624\\u062F\\u0628\\u0629. \\u0648\\u0631\\u0627\\u062D\\u062A."
t["Had it right there and let it go."] = "\\u0643\\u0627\\u0646\\u062A \\u0628\\u0625\\u064A\\u062F\\u064A \\u0648\\u0636\\u064A\\u0639\\u062A\\u0647\\u0627."
t["Had the urge to wave at one of them. Like a neighbour. Didn't."] = "\\u062C\\u062A\\u0646\\u064A \\u0631\\u063A\\u0628\\u0629 \\u0633\\u0644\\u0651\\u0645 \\u0639\\u0644\\u0649 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0645. \\u0645\\u062A\\u0644 \\u062C\\u0627\\u0631. \\u0645\\u0627 \\u0639\\u0645\\u0644\\u062A\\u0647\\u0627."
t["Hand over the weapon. Now. Nothing personal."] = "\\u0633\\u0644\\u0651\\u0645 \\u0627\\u0644\\u0633\\u0644\\u0627\\u062D. \\u0647\\u0644\\u0623. \\u0645\\u0648 \\u0634\\u064A \\u0634\\u062E\\u0635\\u064A."
t["Hands off me!"] = "\\u0634\\u064A\\u0644 \\u0625\\u064A\\u062F\\u0643 \\u0639\\u0646\\u064A!"
t["Hands unsteady, breathing too fast. Pausing until both settle."] = "\\u0627\\u0644\\u0625\\u064A\\u062F\\u064A\\u0646 \\u0639\\u0645 \\u064A\\u0631\\u062C\\u0641\\u0648\\u0627\\u060C \\u0627\\u0644\\u0646\\u0641\\u0633 \\u0633\\u0631\\u064A\\u0639. \\u0648\\u0627\\u0642\\u0641\\u0629 \\u0644\\u062A\\u0647\\u062F\\u0649 \\u0627\\u0644\\u062A\\u0646\\u062A\\u064A\\u0646."
t["Hands where I can see them, weapon down!"] = "\\u0625\\u064A\\u062F\\u064A\\u0643 \\u0648\\u064A\\u0646 \\u0628\\u0634\\u0648\\u0641\\u0647\\u0646\\u060C \\u0648\\u0627\\u0644\\u0633\\u0644\\u0627\\u062D \\u0639\\u0627\\u0644\\u0623\\u0631\\u0636!"
t["Hang on, that is actually worth learning."] = "\\u0627\\u0633\\u062A\\u0646\\u0649\\u060C \\u0647\\u0627\\u062F \\u0641\\u0639\\u0644\\u0627\\u064B \\u0628\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0646\\u062A\\u0639\\u0644\\u0645\\u0647."
t["Harvest complete. Moving output to storage."] = "\\u062E\\u0644\\u0635 \\u0627\\u0644\\u062D\\u0635\\u0627\\u062F. \\u0639\\u0645 \\u0627\\u0646\\u0642\\u0644 \\u0627\\u0644\\u063A\\u0644\\u0629 \\u0639\\u0627\\u0644\\u0645\\u062E\\u0632\\u0646."
t["Harvest is in."] = "\\u0627\\u0644\\u0645\\u062D\\u0635\\u0648\\u0644 \\u0635\\u0627\\u0631 \\u062C\\u0648\\u0627."
t["Harvest is in. We can postpone starvation again."] = "\\u0627\\u0644\\u062D\\u0635\\u0627\\u062F \\u062E\\u0644\\u0635. \\u0645\\u0646\\u0642\\u062F\\u0631 \\u0646\\u0623\\u062C\\u0644 \\u0627\\u0644\\u0645\\u062C\\u0627\\u0639\\u0629 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["Harvest time. Something went according to plan."] = "\\u0648\\u0642\\u062A \\u0627\\u0644\\u062D\\u0635\\u0627\\u062F. \\u0634\\u064A \\u0645\\u0634\\u064A \\u0645\\u062A\\u0644 \\u0627\\u0644\\u062E\\u0637\\u0629."
t["Harvesting now and preserving the seed reserve."] = "\\u0639\\u0645 \\u0627\\u062D\\u0635\\u062F \\u0648\\u062E\\u0628\\u0651\\u064A \\u0628\\u0632\\u0627\\u0631 \\u0644\\u0644\\u062C\\u0627\\u064A."
t["He went quietly. Eventually."] = "\\u0631\\u0627\\u062D \\u0628\\u0647\\u062F\\u0648\\u0621. \\u0628\\u0627\\u0644\\u0622\\u062E\\u0631 \\u064A\\u0639\\u0646\\u064A."
t["He's not hungry any more. Silver linings."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u062C\\u0648\\u0639\\u0627\\u0646. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0634\\u0648\\u0641 \\u0627\\u0644\\u0648\\u062C\\u0647 \\u0627\\u0644\\u062D\\u0644\\u0648."
t["Heads up! We've got a zombie!"] = "\\u0641\\u062A\\u0651\\u062D \\u0639\\u064A\\u0646\\u0643! \\u0641\\u064A \\u0632\\u0648\\u0645\\u0628\\u064A!"
t["Health's too low for another exchange."] = "\\u0635\\u062D\\u062A\\u064A \\u0645\\u0627 \\u0628\\u062A\\u062A\\u062D\\u0645\\u0644 \\u062C\\u0648\\u0644\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["Hear that? A real voice through all this noise."] = "\\u0633\\u0627\\u0645\\u0639\\u061F \\u0635\\u0648\\u062A \\u062D\\u0642\\u064A\\u0642\\u064A \\u0645\\u0646 \\u0628\\u064A\\u0646 \\u0643\\u0644 \\u0647\\u0627\\u0644\\u0636\\u062C\\u0629."
t["Heck of a crush. I'm getting clear."] = "\\u064A\\u0627 \\u0633\\u0627\\u062A\\u0631 \\u0634\\u0648 \\u0647\\u0627\\u0644\\u0639\\u062C\\u0642\\u0629. \\u0639\\u0645 \\u0637\\u0644\\u0639 \\u0645\\u0646\\u0647\\u0627."
t["Heck of a happy hour. Everybody's still here."] = "\\u0634\\u0648 \\u0647\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 \\u0627\\u0644\\u0633\\u0639\\u064A\\u062F\\u0629. \\u0627\\u0644\\u0643\\u0644 \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646."
t["Heck of a minute. I'm back with you now."] = "\\u064A\\u0627 \\u0633\\u0627\\u062A\\u0631 \\u0634\\u0648 \\u0647\\u0627\\u0644\\u062F\\u0642\\u064A\\u0642\\u0629. \\u0631\\u062C\\u0639\\u062A \\u0645\\u0639\\u0643."
t["Heck, I can't keep pretending that run was fine."] = "\\u0648\\u0627\\u0644\\u0644\\u0647 \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0644 \\u0645\\u062B\\u0651\\u0644 \\u0625\\u0646\\u0647 \\u0647\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0643\\u0627\\u0646 \\u0645\\u0646\\u064A\\u062D."
t["Heck, at this rate the dead will die of boredom."] = "\\u0648\\u0627\\u0644\\u0644\\u0647\\u060C \\u0639\\u0647\\u0627\\u0644\\u062D\\u0627\\u0644 \\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0631\\u062D \\u064A\\u0645\\u0648\\u062A\\u0648\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0644\\u0644."
t["Heights make my thoughts lean over the edge before I do."] = "\\u0627\\u0644\\u0639\\u0644\\u0648 \\u0628\\u064A\\u062E\\u0644\\u064A \\u0623\\u0641\\u0643\\u0627\\u0631\\u064A \\u062A\\u0645\\u064A\\u0644 \\u0639\\u0627\\u0644\\u062D\\u0627\\u0641\\u0629 \\u0642\\u0628\\u0644\\u064A."
t["Helicopter. It isn't here for us."] = "\\u062D\\u0648\\u0651\\u0627\\u0645\\u0629. \\u0645\\u0648 \\u062C\\u0627\\u064A\\u0629 \\u0644\\u0639\\u0646\\u0627."
t["Hell of a crush. I'm getting clear."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u0639\\u062C\\u0642\\u0629. \\u0639\\u0645 \\u0637\\u0644\\u0639 \\u0645\\u0646\\u0647\\u0627."
t["Hell of a happy hour. Everybody's still here."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u064A\\u0643 \\u0633\\u0627\\u0639\\u0629 \\u0633\\u0639\\u064A\\u062F\\u0629. \\u0627\\u0644\\u0643\\u0644 \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646."
t["Hell of a minute. I'm back with you now."] = "\\u064A\\u0644\\u0639\\u0646 \\u0647\\u0627\\u0644\\u062F\\u0642\\u064A\\u0642\\u0629 \\u0634\\u0648 \\u0637\\u0648\\u064A\\u0644\\u0629. \\u0631\\u062C\\u0639\\u062A \\u0645\\u0639\\u0643."
t["Hell, I can't keep pretending that run was fine."] = "\\u064A\\u0644\\u0639\\u0646\\u060C \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0644 \\u0645\\u062B\\u0651\\u0644 \\u0625\\u0646\\u0647 \\u0647\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0643\\u0627\\u0646 \\u0645\\u0646\\u064A\\u062D."
t["Hell, at this rate the dead will die of boredom."] = "\\u064A\\u0644\\u0639\\u0646\\u060C \\u0639\\u0647\\u0627\\u0644\\u062D\\u0627\\u0644 \\u0627\\u0644\\u0645\\u064A\\u062A\\u064A\\u0646 \\u0631\\u062D \\u064A\\u0645\\u0648\\u062A\\u0648\\u0627 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0644\\u0644."
t["Hello there. You alone out here?"] = "\\u0623\\u0647\\u0644\\u064A\\u0646. \\u0644\\u062D\\u0627\\u0644\\u0643 \\u0647\\u0648\\u0646\\u061F"
t["Hello, %1. I will keep my hands where you can see them."] = "\\u0623\\u0647\\u0644\\u064A\\u0646 \\u064A\\u0627 %1. \\u0631\\u062D \\u062E\\u0644\\u064A \\u0625\\u064A\\u062F\\u064A\\u064A \\u0648\\u064A\\u0646 \\u0628\\u062A\\u0634\\u0648\\u0641\\u0647\\u0646."
t["Hello, %1. I'll keep my hands where you can see them."] = "\\u0623\\u0647\\u0644\\u064A\\u0646 \\u064A\\u0627 %1. \\u0631\\u062D \\u062E\\u0644\\u064A \\u0625\\u064A\\u062F\\u064A\\u064A \\u0648\\u064A\\u0646 \\u0628\\u062A\\u0634\\u0648\\u0641\\u0647\\u0645."
t["Hello, %1. Nice to remember people can still be polite."] = "\\u0623\\u0647\\u0644\\u064A\\u0646 \\u064A\\u0627 %1. \\u062D\\u0644\\u0648 \\u0627\\u062A\\u0630\\u0643\\u0631 \\u0625\\u0646\\u0648 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0644\\u0633\\u0627 \\u0628\\u062A\\u0639\\u0631\\u0641 \\u062A\\u062A\\u0647\\u0630\\u0628."
t["Hello, %1. Talking first works for me."] = "\\u0623\\u0647\\u0644\\u064A\\u0646 \\u064A\\u0627 %1. \\u0627\\u0644\\u062D\\u0643\\u064A \\u0623\\u0648\\u0644 \\u0634\\u064A \\u0628\\u064A\\u0646\\u0627\\u0633\\u0628\\u0646\\u064A."
t["Hello. Been a rough few days, but I am still here."] = "\\u0623\\u0647\\u0644\\u064A\\u0646. \\u0643\\u0627\\u0645 \\u064A\\u0648\\u0645 \\u0635\\u0639\\u0628\\u064A\\u0646\\u060C \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646."
t["Hello. Easy now. My name is %1."] = "\\u0623\\u0647\\u0644\\u064A\\u0646. \\u0639\\u0644\\u0649 \\u0645\\u0647\\u0644\\u0643. \\u0627\\u0633\\u0645\\u064A %1."
t["Hello. Stay where I can see you, please. I am %1."] = "\\u0623\\u0647\\u0644\\u064A\\u0646. \\u062E\\u0644\\u064A\\u0643 \\u0648\\u064A\\u0646 \\u0628\\u0634\\u0648\\u0641\\u0643 \\u0644\\u0648 \\u0633\\u0645\\u062D\\u062A. \\u0623\\u0646\\u0627 %1."
t["Hello. We can talk before anybody makes a bad decision. I am %1."] = "\\u0623\\u0647\\u0644\\u064A\\u0646. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0643\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0627\\u062E\\u062F \\u0642\\u0631\\u0627\\u0631 \\u063A\\u0644\\u0637. \\u0623\\u0646\\u0627 %1."
t["Help - I don't want to leave you like this!"] = "\\u0633\\u0627\\u0639\\u062F\\u0646\\u064A - \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u062A\\u0631\\u0643\\u0643 \\u0647\\u064A\\u0643!"
t["Help me! I can't get my arms free!"] = "\\u0633\\u0627\\u0639\\u062F\\u0646\\u064A! \\u0645\\u0627 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u062D\\u0631\\u0631 \\u0625\\u064A\\u062F\\u064A\\u064A!"
t["Help! I'm down!"] = "\\u0633\\u0627\\u0639\\u062F\\u0646\\u064A! \\u0648\\u0642\\u0639\\u062A!"
t["Help! Right now, please!"] = "\\u0633\\u0627\\u0639\\u062F\\u0648\\u0646\\u064A! \\u0647\\u0644\\u0623\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643\\u0645!"
t["Here is the position:"] = "\\u0627\\u0644\\u0648\\u0636\\u0639 \\u0647\\u064A\\u0643:"
t["Here is the truth:"] = "\\u0647\\u064A \\u0627\\u0644\\u062D\\u0642\\u064A\\u0642\\u0629:"
t["Here is what matters:"] = "\\u0627\\u0644\\u0645\\u0647\\u0645:"
t["Here we go!"] = "\\u064A\\u0644\\u0627 \\u0628\\u064A\\u0646\\u0627!"
t["Here's %1. Nobody drift off alone."] = "\\u0647\\u064A %1. \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0636\\u064A\\u0639 \\u0644\\u062D\\u0627\\u0644\\u0647."
t["Here's your eviction notice!"] = "\\u0647\\u0627\\u062F \\u0625\\u062E\\u0644\\u0627\\u0621 \\u0631\\u0633\\u0645\\u064A, \\u0628\\u0631\\u0627!"
t["Here. I thought you might like this."] = "\\u062E\\u062F. \\u0641\\u0643\\u0631\\u062A \\u064A\\u0639\\u062C\\u0628\\u0643."
t["Here. The bleeding should stop in a minute."] = "\\u062A\\u0641\\u0636\\u0644. \\u0627\\u0644\\u062F\\u0645 \\u0644\\u0627\\u0632\\u0645 \\u064A\\u0648\\u0642\\u0641 \\u0628\\u062F\\u0642\\u064A\\u0642\\u0629."
t["Hey there, neighbor. Bye, neighbor!"] = "\\u0623\\u0647\\u0644\\u0627 \\u064A\\u0627 \\u062C\\u0627\\u0631. \\u0645\\u0639 \\u0627\\u0644\\u0633\\u0644\\u0627\\u0645\\u0629 \\u064A\\u0627 \\u062C\\u0627\\u0631!"
t["Hey there. I am %1. We are not looking for trouble."] = "\\u0645\\u0631\\u062D\\u0628\\u0627. \\u0623\\u0646\\u0627 %1. \\u0645\\u0648 \\u0639\\u0645 \\u0646\\u062F\\u0648\\u0631 \\u0639\\u0644\\u0649 \\u0645\\u0634\\u0627\\u0643\\u0644."
t["Hey! Nice to meet somebody with a pulse. I am %1."] = "\\u0645\\u0631\\u062D\\u0628\\u0627! \\u062D\\u0644\\u0648 \\u0642\\u0627\\u0628\\u0644 \\u062D\\u062F\\u0627 \\u0625\\u0644\\u0647 \\u0646\\u0628\\u0636. \\u0623\\u0646\\u0627 %1."
t["Hey! Watch your swing."] = "\\u0648\\u0644\\u0643! \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0644\\u0636\\u0631\\u0628\\u062A\\u0643."
t["Hey, friendlies on this side!"] = "\\u0647\\u064A\\u060C \\u0646\\u062D\\u0646\\u0627 \\u0645\\u0639\\u0643\\u0645 \\u0628\\u0647\\u0627\\u0644\\u062C\\u0647\\u0629!"
t["Hey, survivor. Good to meet you while we are both still breathing."] = "\\u0645\\u0631\\u062D\\u0628\\u0627 \\u064A\\u0627 \\u0646\\u0627\\u062C\\u064A. \\u062D\\u0644\\u0648 \\u0646\\u062A\\u0639\\u0631\\u0641 \\u0648\\u0646\\u062D\\u0646\\u0627 \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0646\\u062A\\u0646\\u0641\\u0633."
t["Hey. Alive, tired, and glad to see company."] = "\\u0645\\u0631\\u062D\\u0628\\u0627. \\u0639\\u0627\\u064A\\u0634\\u0629\\u060C \\u062A\\u0639\\u0628\\u0627\\u0646\\u0629\\u060C \\u0648\\u0645\\u0628\\u0633\\u0648\\u0637\\u0629 \\u0628\\u0627\\u0644\\u0648\\u0646\\u0633."
t["Hey. Thanks for saying something before pointing a weapon."] = "\\u0645\\u0631\\u062D\\u0628\\u0627. \\u0634\\u0643\\u0631\\u0627\\u064B \\u0625\\u0646\\u0643 \\u062D\\u0643\\u064A\\u062A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u0648\\u062C\\u0647 \\u0633\\u0644\\u0627\\u062D."
t["Hey. We can keep our distance. Just wanted to say hello."] = "\\u0645\\u0631\\u062D\\u0628\\u0627. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0636\\u0644 \\u0628\\u0639\\u0627\\u062F. \\u0628\\u0633 \\u062D\\u0628\\u064A\\u062A \\u0633\\u0644\\u0645."
t["Hi, %1. I am okay. Thank you for asking."] = "\\u0645\\u0631\\u062D\\u0628\\u0627 \\u064A\\u0627 %1. \\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0634\\u0643\\u0631\\u0627\\u064B \\u0625\\u0646\\u0643 \\u0633\\u0623\\u0644\\u062A."
t["Hi, %1. I was starting to think everyone was gone."] = "\\u0645\\u0631\\u062D\\u0628\\u0627 \\u064A\\u0627 %1. \\u0643\\u0646\\u062A \\u0628\\u0644\\u0634\\u062A \\u0641\\u0643\\u0631 \\u0625\\u0646\\u0648 \\u0627\\u0644\\u0643\\u0644 \\u0631\\u0627\\u062D."
t["Hi, %1. It's good to see another person."] = "\\u0623\\u0647\\u0644\\u064A\\u0646 \\u064A\\u0627 %1. \\u0645\\u0646\\u064A\\u062D \\u0634\\u0648\\u0641 \\u0625\\u0646\\u0633\\u0627\\u0646 \\u062A\\u0627\\u0646\\u064A."
t["Hi. Another living face is good to see. I am %1."] = "\\u0645\\u0631\\u062D\\u0628\\u0627. \\u062D\\u0644\\u0648 \\u0634\\u0648\\u0641 \\u0648\\u062C\\u0647 \\u0639\\u0627\\u064A\\u0634. \\u0623\\u0646\\u0627 %1."
t["Hi. Are you hurt? I am %1."] = "\\u0645\\u0631\\u062D\\u0628\\u0627. \\u0645\\u0635\\u0627\\u0628\\u061F \\u0623\\u0646\\u0627 %1."
t["Hi. Been a while since I met somebody who could answer back."] = "\\u0645\\u0631\\u062D\\u0628\\u0627. \\u0645\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0627 \\u0634\\u0641\\u062A \\u062D\\u062F\\u0627 \\u0628\\u064A\\u0631\\u062F."
t["Hi. It's good to see you standing. I am %1."] = "\\u0623\\u0647\\u0644\\u064A\\u0646. \\u0645\\u0646\\u064A\\u062D \\u0634\\u0641\\u062A\\u0643 \\u0648\\u0627\\u0642\\u0641 \\u0639\\u0625\\u062C\\u0631\\u064A\\u0643. \\u0623\\u0646\\u0627 %1."
t["Hit the one over my shoulders first!"] = "\\u0627\\u0636\\u0631\\u0628 \\u0627\\u0644\\u0644\\u064A \\u0641\\u0648\\u0642 \\u0643\\u062A\\u0627\\u0641\\u064A \\u0623\\u0648\\u0644!"
t["Hold it. Leave now and you keep what you have."] = "\\u0648\\u0642\\u0641. \\u0631\\u0648\\u062D \\u0647\\u0644\\u0623 \\u0648\\u0628\\u062A\\u0636\\u0644 \\u0623\\u063A\\u0631\\u0627\\u0636\\u0643 \\u0645\\u0639\\u0643."
t["Hold it. This place is claimed."] = "\\u0648\\u0642\\u0641. \\u0647\\u0627\\u0644\\u0645\\u0637\\u0631\\u062D \\u0625\\u0644\\u0647 \\u0623\\u0635\\u062D\\u0627\\u0628."
t["Hold my hand, %1. Just for a little while."] = "\\u0627\\u0645\\u0633\\u0643 \\u0625\\u064A\\u062F\\u064A \\u064A\\u0627 %1. \\u0628\\u0633 \\u0634\\u0648\\u064A."
t["Hold on, hold on. I have a bite."] = "\\u0627\\u0633\\u062A\\u0646\\u0649\\u060C \\u0627\\u0633\\u062A\\u0646\\u0649. \\u0641\\u064A \\u0634\\u064A \\u0639\\u0636."
t["Hold on, plants. Water is coming."] = "\\u0627\\u0635\\u0628\\u0631\\u0648\\u0627 \\u064A\\u0627 \\u0632\\u0631\\u0639. \\u0627\\u0644\\u0645\\u064A \\u062C\\u0627\\u064A\\u0629."
t["Hold still while I get this dirty wrap off."] = "\\u062B\\u0628\\u062A \\u0644\\u062D\\u062A\\u0649 \\u0634\\u064A\\u0644 \\u0647\\u0627\\u0644\\u0644\\u0641\\u0629 \\u0627\\u0644\\u0648\\u0633\\u062E\\u0629."
t["Hold still. Small wounds become large problems."] = "\\u062B\\u0628\\u062A. \\u0627\\u0644\\u062C\\u0631\\u0648\\u062D \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631\\u0629 \\u0628\\u062A\\u0635\\u064A\\u0631 \\u0645\\u0634\\u0627\\u0643\\u0644 \\u0643\\u0628\\u064A\\u0631\\u0629."
t["Hold still. This won't take long!"] = "\\u0627\\u062B\\u0628\\u062A. \\u0645\\u0627 \\u0631\\u062D \\u0637\\u0648\\u0644!"
t["Hold that there while I tie it off."] = "\\u0627\\u0645\\u0633\\u0643 \\u0647\\u0648\\u0646 \\u0644\\u062D\\u062A\\u0649 \\u0627\\u0631\\u0628\\u0637\\u0647\\u0627."
t["Hold that thought until we have something real to celebrate."] = "\\u062E\\u0644\\u064A\\u0647\\u0627 \\u0644\\u0646\\u0635\\u064A\\u0631 \\u0639\\u0646\\u0627 \\u0634\\u064A \\u062D\\u0642\\u064A\\u0642\\u064A \\u0646\\u062D\\u062A\\u0641\\u0644 \\u0641\\u064A\\u0647."
t["Hold there. We can settle this with words."] = "\\u0648\\u0642\\u0641 \\u0639\\u0646\\u062F\\u0643. \\u0641\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0644\\u0647\\u0627 \\u0628\\u0627\\u0644\\u062D\\u0643\\u064A."
t["Hold up! I'm not one of them."] = "\\u0627\\u0633\\u062A\\u0646\\u0649! \\u0623\\u0646\\u0627 \\u0645\\u0648 \\u0645\\u0646\\u0647\\u0645."
t["Home sweet hellhole. Pass the beans."] = "\\u0628\\u064A\\u062A\\u064A \\u064A\\u0627 \\u062C\\u0647\\u0646\\u0645\\u064A. \\u0646\\u0627\\u0648\\u0644\\u0646\\u064A \\u0627\\u0644\\u0641\\u0627\\u0635\\u0648\\u0644\\u064A\\u0627."
t["Home sweet home. Pass the beans."] = "\\u0628\\u064A\\u062A\\u064A \\u064A\\u0627 \\u0628\\u064A\\u062A\\u064A. \\u0646\\u0627\\u0648\\u0644\\u0646\\u064A \\u0627\\u0644\\u0641\\u0627\\u0635\\u0648\\u0644\\u064A\\u0627."
t["Honestly? I am still grieving %1."] = "\\u0628\\u0635\\u0631\\u0627\\u062D\\u0629\\u061F \\u0644\\u0633\\u0627 \\u0642\\u0644\\u0628\\u064A \\u0645\\u062D\\u0631\\u0648\\u0642 \\u0639\\u0644\\u0649 %1."
t["Honestly? I feel pretty good today."] = "\\u0628\\u0635\\u0631\\u0627\\u062D\\u0629\\u061F \\u0645\\u0628\\u0633\\u0648\\u0637\\u0629 \\u0627\\u0644\\u064A\\u0648\\u0645."
t["Hook is empty. I will reset the line."] = "\\u0627\\u0644\\u0635\\u0646\\u0627\\u0631\\u0629 \\u0641\\u0627\\u0636\\u064A\\u0629. \\u0631\\u062D \\u0631\\u062C\\u0651\\u0639 \\u0627\\u0644\\u062E\\u064A\\u0637."
t["Horde ahead. Quietly back the way we came."] = "\\u0645\\u0648\\u062C\\u0629 \\u0642\\u062F\\u0627\\u0645\\u0646\\u0627. \\u0628\\u0647\\u062F\\u0648\\u0621, \\u0645\\u0646 \\u0646\\u0641\\u0633 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642."
t["Horde confirmed. This route is closed."] = "\\u0645\\u0648\\u062C\\u0629 \\u0623\\u0643\\u064A\\u062F. \\u0647\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0645\\u0633\\u0643\\u0631."
t["Horde contact. Do not stop moving!"] = "\\u0645\\u0648\\u062C\\u0629 \\u0639\\u0644\\u064A\\u0646\\u0627. \\u0644\\u0627 \\u062A\\u0648\\u0642\\u0641!"
t["Horde contact. Full withdrawal."] = "\\u0645\\u0648\\u062C\\u0629. \\u0627\\u0646\\u0633\\u062D\\u0627\\u0628 \\u0643\\u0627\\u0645\\u0644."
t["Horde moving this way. We need to disappear."] = "\\u0627\\u0644\\u0645\\u0648\\u062C\\u0629 \\u062C\\u0627\\u064A\\u0629 \\u0644\\u0647\\u0648\\u0646. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u062E\\u062A\\u0641\\u064A."
t["Horde on top of us! Go, go!"] = "\\u0627\\u0644\\u0645\\u0648\\u062C\\u0629 \\u0641\\u0648\\u0642\\u0646\\u0627! \\u0631\\u0648\\u062D, \\u0631\\u0648\\u062D!"
t["Horde on us! Break through!"] = "\\u0627\\u0644\\u0645\\u0648\\u062C\\u0629 \\u0639\\u0644\\u064A\\u0646\\u0627! \\u0634\\u0642 \\u0648\\u0641\\u0644!"
t["Horde! Break sight and keep going!"] = "\\u0645\\u0648\\u062C\\u0629! \\u063A\\u064A\\u0628 \\u0639\\u0646 \\u0639\\u064A\\u0646\\u0646 \\u0648\\u0643\\u0645\\u0644!"
t["Horde! Courage won't fix those numbers."] = "\\u0645\\u0648\\u062C\\u0629! \\u0627\\u0644\\u0634\\u062C\\u0627\\u0639\\u0629 \\u0645\\u0627 \\u0628\\u062A\\u0635\\u0644\\u062D \\u0647\\u0627\\u0644\\u0639\\u062F\\u062F."
t["Horde! Fight only to escape!"] = "\\u0645\\u0648\\u062C\\u0629! \\u0642\\u0627\\u062A\\u0644 \\u0628\\u0633 \\u0644\\u062A\\u0647\\u0631\\u0628!"
t["Horde! Nobody plays hero. Move!"] = "\\u0645\\u0648\\u062C\\u0629! \\u0628\\u0644\\u0627 \\u0628\\u0637\\u0648\\u0644\\u0627\\u062A. \\u062A\\u062D\\u0631\\u0643!"
t["Horde! One opening, then we move!"] = "\\u0645\\u0648\\u062C\\u0629! \\u0641\\u062A\\u062D\\u0629 \\u0648\\u062D\\u062F\\u0629 \\u0648\\u0645\\u0646\\u0645\\u0634\\u064A!"
t["Horde! Run as soon as you can!"] = "\\u0645\\u0648\\u062C\\u0629! \\u0627\\u0631\\u0643\\u0636 \\u0623\\u0648\\u0644 \\u0645\\u0627 \\u062A\\u0642\\u062F\\u0631!"
t["Horde! Run!"] = "\\u0645\\u0648\\u062C\\u0629! \\u0627\\u0631\\u0643\\u0636!"
t["Horde! We hit once and get out!"] = "\\u0645\\u0648\\u062C\\u0629! \\u0645\\u0646\\u0636\\u0631\\u0628 \\u0645\\u0631\\u0629 \\u0648\\u0645\\u0646\\u0641\\u0644!"
t["Horde. Engagement objective is escape only."] = "\\u0645\\u0648\\u062C\\u0629. \\u0627\\u0644\\u0647\\u062F\\u0641 \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F \\u0627\\u0644\\u0647\\u0631\\u0628."
t["Horn nearby. Living or dead, they'll all head that way."] = "\\u0632\\u0645\\u0648\\u0631 \\u0642\\u0631\\u064A\\u0628. \\u0627\\u0644\\u0623\\u062D\\u064A\\u0627 \\u0648\\u0627\\u0644\\u0623\\u0645\\u0648\\u0627\\u062A\\u060C \\u0643\\u0644\\u0647\\u0646 \\u0631\\u062D \\u064A\\u0631\\u0648\\u062D\\u0648\\u0627 \\u0644\\u0647\\u0646\\u064A\\u0643."
t["Hospitals like this ran on double shifts. I still dream about the call buttons."] = "\\u0645\\u0634\\u0627\\u0641\\u064A \\u0645\\u062A\\u0644 \\u0647\\u064A \\u0643\\u0627\\u0646\\u062A \\u062A\\u0645\\u0634\\u064A \\u0639\\u0627\\u0644\\u0645\\u0646\\u0627\\u0648\\u0628\\u0627\\u062A \\u0627\\u0644\\u062F\\u0628\\u0644. \\u0644\\u0633\\u0627 \\u0628\\u062D\\u0644\\u0645 \\u0628\\u0623\\u0632\\u0631\\u0627\\u0631 \\u0627\\u0644\\u0646\\u062F\\u0627\\u0621."
t["Hospitals went first. Everybody came here to get better."] = "\\u0627\\u0644\\u0645\\u0634\\u0627\\u0641\\u064A \\u0633\\u0642\\u0637\\u062A \\u0623\\u0648\\u0644. \\u0627\\u0644\\u0643\\u0644 \\u0625\\u062C\\u0627 \\u0644\\u0647\\u0648\\u0646 \\u0644\\u064A\\u0637\\u064A\\u0628."
t["Hot soup would do. Something with a spoon and no hurry."] = "\\u0634\\u0648\\u0631\\u0628\\u0629 \\u0633\\u062E\\u0646\\u0629 \\u0628\\u062A\\u0645\\u0634\\u064A. \\u0634\\u064A \\u0628\\u0627\\u0644\\u0645\\u0639\\u0644\\u0642\\u0629 \\u0648\\u0628\\u0644\\u0627 \\u0639\\u062C\\u0644\\u0629."
t["House alarm. Whoever set that off is already regretting it."] = "\\u0625\\u0646\\u0630\\u0627\\u0631 \\u0628\\u064A\\u062A. \\u0627\\u0644\\u0644\\u064A \\u0637\\u0644\\u0639\\u0647 \\u0647\\u0644\\u0623 \\u0646\\u062F\\u0645\\u0627\\u0646."
t["How long before we make another supply trip?"] = "\\u0642\\u062F\\u064A\\u0634 \\u0628\\u062F\\u0646\\u0627 \\u0644\\u0646\\u0637\\u0644\\u0639 \\u0645\\u0634\\u0648\\u0627\\u0631 \\u0645\\u0648\\u0646\\u0629 \\u062A\\u0627\\u0646\\u064A\\u061F"
t["Hum along if you know the last verse."] = "\\u062F\\u0646\\u062F\\u0646 \\u0645\\u0639\\u064A \\u0625\\u0630\\u0627 \\u0628\\u062A\\u0639\\u0631\\u0641 \\u0622\\u062E\\u0631 \\u0645\\u0642\\u0637\\u0639."
t["Hunger can wait a little. Not forever."] = "\\u0627\\u0644\\u062C\\u0648\\u0639 \\u0641\\u064A\\u0647 \\u064A\\u0633\\u062A\\u0646\\u0649 \\u0634\\u0648\\u064A. \\u0645\\u0648 \\u0639\\u0637\\u0648\\u0644."
t["Hunger is becoming noticeable."] = "\\u0627\\u0644\\u062C\\u0648\\u0639 \\u0635\\u0627\\u0631 \\u0645\\u0644\\u062D\\u0648\\u0638."
t["Hunger is impairing me. Food is now a priority."] = "\\u0627\\u0644\\u062C\\u0648\\u0639 \\u0639\\u0645 \\u064A\\u0623\\u062B\\u0631 \\u0639\\u0644\\u064A\\u064A. \\u0627\\u0644\\u0623\\u0643\\u0644 \\u0635\\u0627\\u0631 \\u0623\\u0648\\u0644\\u0648\\u064A\\u0629."
t["Hunger is making it hard to concentrate."] = "\\u0627\\u0644\\u062C\\u0648\\u0639 \\u0639\\u0645 \\u064A\\u0635\\u0639\\u0651\\u0628 \\u0639\\u0644\\u064A\\u064A \\u0631\\u0643\\u0651\\u0632."
t["I almost called for %1 again. Habit hasn't caught up."] = "\\u0643\\u0646\\u062A \\u0631\\u062D \\u0646\\u0627\\u062F\\u064A %1 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629. \\u0627\\u0644\\u0639\\u0627\\u062F\\u0629 \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0627\\u0633\\u062A\\u0648\\u0639\\u0628\\u062A."
t["I always want to drop something off a roof. Just to watch."] = "\\u062F\\u0627\\u064A\\u0645\\u064B\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0648\\u0642\\u0639 \\u0634\\u064A \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0637\\u062D. \\u0628\\u0633 \\u0644\\u0627\\u062A\\u0641\\u0631\\u062C."
t["I am alive. Give me a little time to come down from that."] = "\\u0639\\u0627\\u064A\\u0634\\u0629. \\u0639\\u0637\\u064A\\u0646\\u064A \\u0634\\u0648\\u064A\\u0629 \\u0648\\u0642\\u062A \\u0644\\u0627\\u0646\\u0632\\u0644 \\u0645\\u0646 \\u0647\\u0627\\u062F."
t["I am all right for now. Ready when you are."] = "\\u0645\\u0646\\u064A\\u062D\\u0629 \\u0644\\u0647\\u0644\\u0623. \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0644\\u0645\\u0627 \\u062A\\u0643\\u0648\\u0646 \\u062C\\u0627\\u0647\\u0632."
t["I am all right, but thank you for checking."] = "\\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629\\u060C \\u0628\\u0633 \\u0634\\u0643\\u0631\\u0627\\u064B \\u0625\\u0646\\u0643 \\u0633\\u0623\\u0644\\u062A."
t["I am all right. How are you holding up?"] = "\\u0645\\u0646\\u064A\\u062D\\u0629. \\u0623\\u0646\\u062A \\u0643\\u064A\\u0641\\u0643\\u061F"
t["I am all right. You can lean on me too, you know."] = "\\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0641\\u064A\\u0643 \\u062A\\u062A\\u0643\\u0649 \\u0639\\u0644\\u064A\\u064A \\u0643\\u0645\\u0627\\u0646\\u060C \\u0628\\u062A\\u0639\\u0631\\u0641."
t["I am bringing this up because I want everyone home alive."] = "\\u0639\\u0645 \\u0627\\u0641\\u062A\\u062D \\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639 \\u0644\\u0623\\u0646\\u064A \\u0628\\u062F\\u064A \\u0627\\u0644\\u0643\\u0644 \\u064A\\u0631\\u062C\\u0639 \\u0639\\u0627\\u064A\\u0634."
t["I am coming, but my place here is not settled yet."] = "\\u062C\\u0627\\u064A\\u0629\\u060C \\u0628\\u0633 \\u0645\\u0637\\u0631\\u062D\\u064A \\u0647\\u0648\\u0646 \\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0645\\u062D\\u0633\\u0648\\u0645."
t["I am conserving ammunition until we restock."] = "\\u0639\\u0645 \\u0648\\u0641\\u0651\\u0631 \\u0627\\u0644\\u0631\\u0635\\u0627\\u0635 \\u0644\\u062D\\u062A\\u0649 \\u0646\\u0639\\u0628\\u0651\\u064A."
t["I am done pretending I can push through this. Water now."] = "\\u062E\\u0644\\u0635\\u060C \\u0645\\u0627 \\u0639\\u062F\\u062A \\u0645\\u062B\\u0651\\u0644 \\u0625\\u0646\\u064A \\u0645\\u062A\\u062D\\u0645\\u0644\\u0629. \\u0645\\u064A \\u0647\\u0644\\u0623."
t["I am falling apart. I need sleep now."] = "\\u0639\\u0645 \\u0627\\u062A\\u0641\\u062A\\u062A. \\u0628\\u062F\\u064A \\u0646\\u0627\\u0645 \\u0647\\u0644\\u0623."
t["I am getting hungry. We should not let that become weakness."] = "\\u0639\\u0645 \\u062C\\u0648\\u0639. \\u0644\\u0627\\u0632\\u0645 \\u0645\\u0627 \\u0646\\u062E\\u0644\\u064A\\u0647 \\u064A\\u0635\\u064A\\u0631 \\u0636\\u0639\\u0641."
t["I am getting thirsty. Let's not let it slow my judgement."] = "\\u0639\\u0645 \\u0639\\u0637\\u0634. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0627 \\u0646\\u062E\\u0644\\u064A\\u0647 \\u064A\\u0623\\u062B\\u0631 \\u0639\\u0644\\u0649 \\u062A\\u0641\\u0643\\u064A\\u0631\\u064A."
t["I am getting tired enough to watch my footing."] = "\\u062A\\u0639\\u0628\\u0627\\u0646\\u0629 \\u0644\\u062F\\u0631\\u062C\\u0629 \\u0644\\u0627\\u0632\\u0645 \\u0627\\u0646\\u062A\\u0628\\u0647 \\u0648\\u064A\\u0646 \\u0639\\u0645 \\u062D\\u0637 \\u0625\\u062C\\u0631\\u064A."
t["I am going home. This is where I belong."] = "\\u0623\\u0646\\u0627 \\u0631\\u0627\\u062C\\u0639\\u0629 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A. \\u0647\\u0648\\u0646 \\u0645\\u0637\\u0631\\u062D\\u064A."
t["I am going to keep to myself for a bit."] = "\\u0631\\u062D \\u0636\\u0644 \\u0644\\u062D\\u0627\\u0644\\u064A \\u0634\\u0648\\u064A."
t["I am good. Save that speech for when one of us really needs it."] = "\\u0623\\u0646\\u0627 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u062E\\u0628\\u0651\\u064A \\u0647\\u0627\\u0644\\u062E\\u0637\\u0628\\u0629 \\u0644\\u0648\\u0642\\u062A \\u064A\\u062D\\u062A\\u0627\\u062C\\u0647\\u0627 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0627 \\u0639\\u0646 \\u062C\\u062F."
t["I am here, but I am not all right."] = "\\u0623\\u0646\\u0627 \\u0647\\u0648\\u0646\\u060C \\u0628\\u0633 \\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D\\u0629."
t["I am holding up. I am still watching our exits."] = "\\u0644\\u0633\\u0627 \\u0635\\u0627\\u0645\\u062F\\u0629. \\u0648\\u0644\\u0633\\u0627 \\u0639\\u064A\\u0646\\u064A \\u0639\\u0627\\u0644\\u0645\\u062E\\u0627\\u0631\\u062C."
t["I am holding up. Our supplies and gear are in order for now."] = "\\u0644\\u0633\\u0627 \\u0635\\u0627\\u0645\\u062F\\u0629. \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629 \\u0648\\u0627\\u0644\\u0639\\u062F\\u0629 \\u0628\\u062E\\u064A\\u0631 \\u0644\\u0647\\u0644\\u0623."
t["I am holding up. Point me where you need me."] = "\\u0644\\u0633\\u0627 \\u0635\\u0627\\u0645\\u062F\\u0629. \\u062F\\u0644\\u0646\\u064A \\u0648\\u064A\\u0646 \\u0628\\u062F\\u0643 \\u064A\\u0627\\u0646\\u064A."
t["I am hungry enough that it is getting hard to focus."] = "\\u062C\\u0648\\u0639\\u0627\\u0646\\u0629 \\u0644\\u062F\\u0631\\u062C\\u0629 \\u0635\\u0627\\u0631 \\u0635\\u0639\\u0628 \\u0631\\u0643\\u0651\\u0632."
t["I am hurt. I need someone to look at this."] = "\\u0623\\u0646\\u0627 \\u0645\\u0635\\u0627\\u0628\\u0629. \\u0628\\u062F\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0634\\u0648\\u0641 \\u0647\\u0627\\u062F."
t["I am listening. I can't turn it around all at once."] = "\\u0639\\u0645 \\u0627\\u0633\\u0645\\u0639\\u0643. \\u0628\\u0633 \\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0642\\u0644\\u0628\\u0647\\u0627 \\u062F\\u0641\\u0639\\u0629 \\u0648\\u062D\\u062F\\u0629."
t["I am managing, but I keep thinking about %1."] = "\\u0645\\u0627\\u0634\\u064A\\u0629 \\u0627\\u0644\\u062D\\u0627\\u0644\\u060C \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0628\\u0641\\u0643\\u0631 \\u0628\\u0640%1."
t["I am missing something personal. I would like it back."] = "\\u0641\\u064A \\u0634\\u064A \\u0634\\u062E\\u0635\\u064A \\u0636\\u0627\\u064A\\u0639\\u0644\\u064A. \\u0648\\u0628\\u062F\\u064A \\u064A\\u0627\\u0647 \\u064A\\u0631\\u062C\\u0639."
t["I am no longer fit for work without fluids."] = "\\u0645\\u0627 \\u0639\\u062F\\u062A \\u0635\\u0627\\u0644\\u062D\\u0629 \\u0644\\u0644\\u0634\\u063A\\u0644 \\u0628\\u0644\\u0627 \\u0633\\u0648\\u0627\\u064A\\u0644."
t["I am no longer fit for work without food."] = "\\u0645\\u0627 \\u0639\\u062F\\u062A \\u0635\\u0627\\u0644\\u062D\\u0629 \\u0644\\u0644\\u0634\\u063A\\u0644 \\u0628\\u0644\\u0627 \\u0623\\u0643\\u0644."
t["I am not afraid of the quiet."] = "\\u0645\\u0648 \\u062E\\u0627\\u064A\\u0641\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0643\\u0648\\u062A."
t["I am not all right yet. %1 is gone, and I need time."] = "\\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D\\u0629. %1 \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0645\\u0639\\u0646\\u0627\\u060C \\u0648\\u0628\\u062F\\u064A \\u0648\\u0642\\u062A."
t["I am not doing well. I am trying to hold it together."] = "\\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0639\\u0645 \\u062D\\u0627\\u0648\\u0644 \\u0636\\u0644 \\u0648\\u0627\\u0642\\u0641\\u0629."
t["I am not feeling well. I need to rest."] = "\\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0628\\u062F\\u064A \\u0627\\u0631\\u062A\\u0627\\u062D."
t["I am not fixed, but I feel steadier. Thank you."] = "\\u0645\\u0627 \\u062A\\u0635\\u0644\\u0651\\u062D\\u062A\\u060C \\u0628\\u0633 \\u0635\\u0631\\u062A \\u0623\\u062A\\u0628\\u062A \\u0634\\u0648\\u064A. \\u0634\\u0643\\u0631\\u0627\\u064B."
t["I am not ready to decide yet. Give me another run."] = "\\u0644\\u0633\\u0627 \\u0645\\u0648 \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0642\\u0631\\u0631. \\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0645\\u0634\\u0648\\u0627\\u0631 \\u0643\\u0645\\u0627\\u0646."
t["I am not ready to talk about that yet."] = "\\u0644\\u0633\\u0627 \\u0645\\u0648 \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0627\\u062D\\u0643\\u064A \\u0628\\u0647\\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639."
t["I am not staying quiet if this keeps happening."] = "\\u0645\\u0627 \\u0631\\u062D \\u0627\\u0633\\u0643\\u062A \\u0625\\u0630\\u0627 \\u0636\\u0644 \\u0647\\u0627\\u0644\\u0634\\u064A \\u064A\\u0635\\u064A\\u0631."
t["I am okay. Let me know if anyone else needs help."] = "\\u062A\\u0645\\u0627\\u0645. \\u0642\\u0644\\u064A \\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u062A\\u0627\\u0646\\u064A \\u0645\\u062D\\u062A\\u0627\\u062C \\u0645\\u0633\\u0627\\u0639\\u062F\\u0629."
t["I am okay. Not good, but okay."] = "\\u0623\\u0646\\u0627 \\u062A\\u0645\\u0627\\u0645. \\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D\\u0629\\u060C \\u0628\\u0633 \\u062A\\u0645\\u0627\\u0645."
t["I am operating below safe capacity."] = "\\u0634\\u063A\\u0651\\u0627\\u0644\\u0629 \\u0628\\u0623\\u0642\\u0644 \\u0645\\u0646 \\u0627\\u0644\\u062D\\u062F \\u0627\\u0644\\u0622\\u0645\\u0646."
t["I am over. My arms have filed a complaint."] = "\\u0642\\u0637\\u0639\\u062A. \\u0625\\u064A\\u062F\\u064A\\u064A \\u0642\\u062F\\u0645\\u0648\\u0627 \\u0634\\u0643\\u0648\\u0649 \\u0631\\u0633\\u0645\\u064A\\u0629."
t["I am panicking. I know it. Just stay near me."] = "\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u0647\\u0644\\u0639. \\u0628\\u0639\\u0631\\u0641. \\u0628\\u0633 \\u062E\\u0644\\u064A\\u0643 \\u062C\\u0646\\u0628\\u064A."
t["I am past tired. I need sleep."] = "\\u062A\\u062C\\u0627\\u0648\\u0632\\u062A \\u0627\\u0644\\u062A\\u0639\\u0628. \\u0628\\u062F\\u064A \\u0646\\u0627\\u0645."
t["I am running out of ways to say I am tired."] = "\\u062E\\u0644\\u0635\\u0648\\u0627 \\u0645\\u0646\\u064A \\u0627\\u0644\\u0637\\u0631\\u0642 \\u0644\\u0642\\u0648\\u0644 \\u0625\\u0646\\u064A \\u062A\\u0639\\u0628\\u0627\\u0646\\u0629."
t["I am short on ammunition. I will save what I have."] = "\\u0631\\u0635\\u0627\\u0635\\u064A \\u0642\\u0644\\u064A\\u0644. \\u0631\\u062D \\u0648\\u0641\\u0651\\u0631 \\u0627\\u0644\\u0644\\u064A \\u0645\\u0639\\u064A."
t["I am showing symptoms, and I don't think this is ordinary sickness."] = "\\u0639\\u0646\\u062F\\u064A \\u0623\\u0639\\u0631\\u0627\\u0636\\u060C \\u0648\\u0645\\u0627 \\u0628\\u0638\\u0646 \\u0647\\u0627\\u062F \\u0645\\u0631\\u0636 \\u0639\\u0627\\u062F\\u064A."
t["I am steady again. Sorry about that."] = "\\u0631\\u062C\\u0639\\u062A \\u0645\\u0646\\u064A\\u062D\\u0629. \\u0622\\u0633\\u0641\\u0629 \\u0639\\u0627\\u0644\\u0644\\u064A \\u0635\\u0627\\u0631."
t["I am still functional, but I need treatment."] = "\\u0644\\u0633\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644\\u060C \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0639\\u0644\\u0627\\u062C."
t["I am still getting to know you. Give me time."] = "\\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0627\\u062A\\u0639\\u0631\\u0641 \\u0639\\u0644\\u064A\\u0643. \\u0627\\u0639\\u0637\\u064A\\u0646\\u064A \\u0648\\u0642\\u062A."
t["I am still here. Please remember this version."] = "\\u0644\\u0633\\u0627 \\u0647\\u0648\\u0646. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u062A\\u0630\\u0643\\u0631\\u0646\\u064A \\u0647\\u064A\\u0643."
t["I am still on my feet, but I need food now."] = "\\u0644\\u0633\\u0627 \\u0648\\u0627\\u0642\\u0641\\u0629\\u060C \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0623\\u0643\\u0644 \\u0647\\u0644\\u0623."
t["I am still weighing it. Do not push me yet."] = "\\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0648\\u0627\\u0632\\u0646\\u0647\\u0627. \\u0644\\u0627 \\u062A\\u0636\\u063A\\u0637 \\u0639\\u0644\\u064A\\u064A \\u0647\\u0644\\u0623."
t["I am too dehydrated for another run."] = "\\u0646\\u0627\\u0634\\u0641\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u062A\\u0627\\u0646\\u064A."
t["I am too tired to be safe. We stop here."] = "\\u062A\\u0639\\u0628\\u0627\\u0646\\u0629 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u0643\\u0648\\u0646 \\u0628\\u0623\\u0645\\u0627\\u0646. \\u0645\\u0646\\u0648\\u0642\\u0641 \\u0647\\u0648\\u0646."
t["I am too wound up. I need somewhere secure to breathe."] = "\\u0623\\u0639\\u0635\\u0627\\u0628\\u064A \\u0645\\u0634\\u062F\\u0648\\u062F\\u0629. \\u0628\\u062F\\u064A \\u0645\\u062D\\u0644 \\u0622\\u0645\\u0646 \\u0627\\u062A\\u0646\\u0641\\u0633 \\u0641\\u064A\\u0647."
t["I am trying not to take this out on anyone."] = "\\u0639\\u0645 \\u062D\\u0627\\u0648\\u0644 \\u0645\\u0627 \\u0627\\u0637\\u0644\\u0651\\u0639\\u0647\\u0627 \\u0628\\u062D\\u062F\\u0627."
t["I am willing to take the risk if the goal matters."] = "\\u062C\\u0627\\u0647\\u0632\\u0629 \\u062E\\u0627\\u0637\\u0631 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0647\\u062F\\u0641 \\u0628\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644."
t["I appreciate it, but I have not earned a victory speech yet."] = "\\u0628\\u0642\\u062F\\u0651\\u0631 \\u0647\\u0627\\u0644\\u0634\\u064A\\u060C \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0627\\u0633\\u062A\\u0627\\u0647\\u0644\\u062A \\u062E\\u0637\\u0628\\u0629 \\u0646\\u0635\\u0631."
t["I appreciate it. I really do."] = "\\u0628\\u0642\\u062F\\u0651\\u0631\\u0647\\u0627. \\u0639\\u0646 \\u062C\\u062F."
t["I appreciate it. Let the words settle for a moment."] = "\\u0628\\u0642\\u062F\\u0651\\u0631 \\u0647\\u0627\\u0644\\u0634\\u064A. \\u062E\\u0644\\u064A \\u0627\\u0644\\u0643\\u0644\\u0627\\u0645 \\u064A\\u0647\\u062F\\u0649 \\u0634\\u0648\\u064A."
t["I appreciate that you're asking, but no."] = "\\u0628\\u0642\\u062F\\u0651\\u0631 \\u0625\\u0646\\u0643 \\u0639\\u0645 \\u062A\\u0633\\u0623\\u0644\\u060C \\u0628\\u0633 \\u0644\\u0623."
t["I asked the screws nicely. They want a tool."] = "\\u062A\\u0631\\u062C\\u064A\\u062A \\u0627\\u0644\\u0628\\u0631\\u0627\\u063A\\u064A \\u0628\\u0623\\u062F\\u0628. \\u0628\\u062F\\u0647\\u0646 \\u0639\\u062F\\u0629."
t["I believe you'll pull your weight. Makes planning simpler."] = "\\u0645\\u0635\\u062F\\u0642\\u0629 \\u0625\\u0646\\u0643 \\u0631\\u062D \\u062A\\u0634\\u064A\\u0644 \\u062D\\u0645\\u0644\\u0643. \\u0647\\u064A\\u0643 \\u0627\\u0644\\u062A\\u062E\\u0637\\u064A\\u0637 \\u0623\\u0633\\u0647\\u0644."
t["I bet the last thing on every radio was a weather report."] = "\\u0628\\u0631\\u0627\\u0647\\u0646 \\u0625\\u0646 \\u0622\\u062E\\u0631 \\u0634\\u064A \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u0631\\u0627\\u062F\\u064A\\u0648 \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0646\\u0634\\u0631\\u0629 \\u0627\\u0644\\u062C\\u0648\\u064A\\u0629."
t["I came looking for news and found a person."] = "\\u0625\\u062C\\u064A\\u062A \\u062F\\u0648\\u0631 \\u0639\\u0627\\u0644\\u0623\\u062E\\u0628\\u0627\\u0631 \\u0648\\u0644\\u0642\\u064A\\u062A \\u0625\\u0646\\u0633\\u0627\\u0646."
t["I came out of that book wanting to ask how everyone is doing."] = "\\u0637\\u0644\\u0639\\u062A \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0643\\u062A\\u0627\\u0628 \\u0648\\u0628\\u062F\\u064A \\u0627\\u0633\\u0623\\u0644 \\u0643\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0643\\u064A\\u0641 \\u062D\\u0627\\u0644\\u0647."
t["I can barely stay awake."] = "\\u0628\\u0627\\u0644\\u0643\\u0627\\u062F \\u0641\\u0627\\u064A\\u0642\\u0629."
t["I can be quiet around you without feeling alone."] = "\\u0628\\u0642\\u062F\\u0631 \\u0627\\u0633\\u0643\\u062A \\u062C\\u0646\\u0628\\u0643 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u062D\\u0633 \\u062D\\u0627\\u0644\\u064A \\u0644\\u062D\\u0627\\u0644\\u064A."
t["I can carry one book on the next trip. Any recommendation, %1?"] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u062D\\u0645\\u0644 \\u0643\\u062A\\u0627\\u0628 \\u0648\\u0627\\u062D\\u062F \\u0628\\u0627\\u0644\\u0645\\u0634\\u0648\\u0627\\u0631 \\u0627\\u0644\\u062C\\u0627\\u064A. \\u0634\\u0648 \\u0628\\u062A\\u0646\\u0635\\u062D\\u0646\\u064A \\u064A\\u0627 %1\\u061F"
t["I can do my job. I just haven't made peace with losing %1."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644. \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0645\\u0627 \\u062A\\u0635\\u0627\\u0644\\u062D\\u062A \\u0645\\u0639 \\u062E\\u0633\\u0627\\u0631\\u0629 %1."
t["I can do this. I just need one breath."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0639\\u0645\\u0644\\u0647\\u0627. \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0646\\u0641\\u0633 \\u0648\\u0627\\u062D\\u062F."
t["I can explain the point now. That means I probably learned it."] = "\\u0635\\u0631\\u062A \\u0641\\u064A\\u0646\\u064A \\u0627\\u0634\\u0631\\u062D \\u0627\\u0644\\u0641\\u0643\\u0631\\u0629. \\u064A\\u0639\\u0646\\u064A \\u0627\\u0644\\u0638\\u0627\\u0647\\u0631 \\u062A\\u0639\\u0644\\u0645\\u062A\\u0647\\u0627."
t["I can face the dead. Apparently quitting is harder."] = "\\u0628\\u0648\\u0627\\u062C\\u0647 \\u0627\\u0644\\u0645\\u0648\\u062A\\u0649. \\u0648\\u0637\\u0644\\u0639 \\u062A\\u0631\\u0643 \\u0627\\u0644\\u062F\\u062E\\u0627\\u0646 \\u0623\\u0635\\u0639\\u0628."
t["I can feel it behind my eyes!"] = "\\u062D\\u0627\\u0633\\u0629 \\u0641\\u064A\\u0647 \\u0648\\u0631\\u0627 \\u0639\\u064A\\u0648\\u0646\\u064A!"
t["I can feel my temper getting shorter."] = "\\u062D\\u0627\\u0633\\u0629 \\u062E\\u0644\\u0642\\u064A \\u0639\\u0645 \\u064A\\u0636\\u064A\\u0642."
t["I can feel pieces of me going missing."] = "\\u062D\\u0627\\u0633\\u0629 \\u0642\\u0637\\u0639 \\u0645\\u0646\\u064A \\u0639\\u0645 \\u062A\\u0636\\u064A\\u0639."
t["I can feel them biting! Get me out!"] = "\\u062D\\u0627\\u0633\\u0629 \\u0641\\u064A\\u0646 \\u0639\\u0645 \\u064A\\u0639\\u0636\\u0648\\u0627! \\u0637\\u0627\\u0644\\u0639\\u0646\\u064A!"
t["I can fight dirt, but I still need a tool."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u062D\\u0627\\u0631\\u0628 \\u0627\\u0644\\u062A\\u0631\\u0627\\u0628\\u060C \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0628\\u062F\\u064A \\u0639\\u062F\\u0629."
t["I can fight hungry, but not well. Find me food."] = "\\u0641\\u064A\\u0646\\u064A \\u0642\\u0627\\u062A\\u0644 \\u062C\\u0648\\u0639\\u0627\\u0646\\u0629\\u060C \\u0628\\u0633 \\u0645\\u0648 \\u0645\\u0646\\u064A\\u062D. \\u062F\\u0628\\u0631\\u0644\\u064A \\u0623\\u0643\\u0644."
t["I can force another mile. I should not have to."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u063A\\u0635\\u0628 \\u062D\\u0627\\u0644\\u064A \\u0645\\u064A\\u0644 \\u0643\\u0645\\u0627\\u0646. \\u0628\\u0633 \\u0645\\u0627 \\u0644\\u0627\\u0632\\u0645."
t["I can force it, but I won't win it like this."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u062C\\u0628\\u0631 \\u062D\\u0627\\u0644\\u064A\\u060C \\u0628\\u0633 \\u0647\\u064A\\u0643 \\u0645\\u0648 \\u0631\\u062D \\u0627\\u0631\\u0628\\u062D."
t["I can forgive one mistake. Two is harder."] = "\\u0628\\u0633\\u0627\\u0645\\u062D \\u063A\\u0644\\u0637\\u0629 \\u0648\\u062D\\u062F\\u0629. \\u0627\\u0644\\u062A\\u0646\\u062A\\u064A\\u0646 \\u0623\\u0635\\u0639\\u0628."
t["I can function. I just can't pretend I am fine."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644. \\u0628\\u0633 \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0645\\u062B\\u0651\\u0644 \\u0625\\u0646\\u064A \\u0645\\u0646\\u064A\\u062D\\u0629."
t["I can get in, but not back out safely."] = "\\u0628\\u0642\\u062F\\u0631 \\u0641\\u0648\\u062A\\u060C \\u0628\\u0633 \\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u0637\\u0644\\u0639 \\u0628\\u0623\\u0645\\u0627\\u0646."
t["I can glare at the forest, but it won't make planks."] = "\\u0641\\u064A\\u0646\\u064A \\u0628\\u062D\\u0644\\u0642 \\u0628\\u0627\\u0644\\u063A\\u0627\\u0628\\u0629 \\u0642\\u062F \\u0645\\u0627 \\u0628\\u062F\\u064A\\u060C \\u0628\\u0633 \\u0645\\u0627 \\u0631\\u062D \\u062A\\u0637\\u0644\\u0639 \\u0623\\u0644\\u0648\\u0627\\u062D."
t["I can hear a walker. Watch the blind side."] = "\\u0633\\u0627\\u0645\\u0639\\u0629 \\u0632\\u0648\\u0645\\u0628\\u064A. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0645\\u0646 \\u0627\\u0644\\u062C\\u0647\\u0629 \\u0627\\u0644\\u0639\\u0645\\u064A\\u0627."
t["I can hear it from the stairs. Let me find a chair."] = "\\u0633\\u0627\\u0645\\u0639\\u062A\\u0647 \\u0645\\u0646 \\u0627\\u0644\\u062F\\u0631\\u062C. \\u062E\\u0644\\u064A\\u0646\\u064A \\u0644\\u0627\\u0642\\u064A \\u0643\\u0631\\u0633\\u064A."
t["I can hear my heart. It's too fast. It's too fast."] = "\\u0639\\u0645 \\u0627\\u0633\\u0645\\u0639 \\u0642\\u0644\\u0628\\u064A. \\u0633\\u0631\\u064A\\u0639 \\u0643\\u062A\\u064A\\u0631. \\u0633\\u0631\\u064A\\u0639 \\u0643\\u062A\\u064A\\u0631."
t["I can hear things besides my heartbeat again."] = "\\u0631\\u062C\\u0639\\u062A \\u0627\\u0633\\u0645\\u0639 \\u0623\\u0634\\u064A\\u0627 \\u063A\\u064A\\u0631 \\u062F\\u0642\\u0627\\u062A \\u0642\\u0644\\u0628\\u064A."
t["I can hear you. Keep talking."] = "\\u0633\\u0627\\u0645\\u0639\\u062A\\u0643. \\u0636\\u0644 \\u0627\\u062D\\u0643\\u064A."
t["I can hold a line. This, less so."] = "\\u0628\\u062B\\u0628\\u062A \\u0639\\u0627\\u0644\\u062C\\u0628\\u0647\\u0629. \\u0628\\u0633 \\u0647\\u0627\\u062F\\u060C \\u0645\\u0648 \\u0643\\u062A\\u064A\\u0631."
t["I can hold here. The approach gives me enough warning."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u062B\\u0628\\u062A \\u0647\\u0648\\u0646. \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0628\\u062A\\u0646\\u0628\\u0647\\u0646\\u064A \\u0642\\u0628\\u0644 \\u0628\\u0648\\u0642\\u062A."
t["I can hold the nails in place. They won't stay there."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0645\\u0633\\u0643 \\u0627\\u0644\\u0628\\u0633\\u0627\\u0645\\u064A\\u0631 \\u0628\\u0645\\u062D\\u0644\\u0647\\u0627. \\u0628\\u0633 \\u0645\\u0627 \\u0631\\u062D \\u064A\\u0636\\u0644\\u0648\\u0627."
t["I can judge the gaps again. Let's keep one open."] = "\\u0631\\u062C\\u0639\\u062A \\u0628\\u0642\\u062F\\u0631 \\u0642\\u062F\\u0651\\u0631 \\u0627\\u0644\\u0641\\u0631\\u0627\\u063A\\u0627\\u062A. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u064A \\u0648\\u0627\\u062D\\u062F\\u0629 \\u0645\\u0641\\u062A\\u0648\\u062D\\u0629."
t["I can keep going, but I am not calm yet."] = "\\u0641\\u064A\\u0646\\u064A \\u0643\\u0645\\u0651\\u0644\\u060C \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0647\\u0627\\u062F\\u064A\\u0629."
t["I can keep going, but not long without water."] = "\\u0641\\u064A\\u0646\\u064A \\u0643\\u0645\\u0651\\u0644\\u060C \\u0628\\u0633 \\u0645\\u0648 \\u0643\\u062A\\u064A\\u0631 \\u0628\\u0644\\u0627 \\u0645\\u064A."
t["I can keep moving, but patch me up when we get a chance."] = "\\u0641\\u064A\\u0646\\u064A \\u0643\\u0645\\u0651\\u0644\\u060C \\u0628\\u0633 \\u0636\\u0645\\u0651\\u062F\\u0646\\u064A \\u0623\\u0648\\u0644 \\u0645\\u0627 \\u062A\\u0633\\u0646\\u062D \\u0641\\u0631\\u0635\\u0629."
t["I can keep moving. Just remember food when we stop."] = "\\u0641\\u064A\\u0646\\u064A \\u0643\\u0645\\u0651\\u0644. \\u0628\\u0633 \\u0644\\u0627 \\u062A\\u0646\\u0633\\u0649 \\u0627\\u0644\\u0623\\u0643\\u0644 \\u0644\\u0645\\u0627 \\u0646\\u0648\\u0642\\u0641."
t["I can live with %2. That's the important part."] = "\\u0641\\u064A\\u0646\\u064A \\u0639\\u064A\\u0634 \\u0645\\u0639 %2. \\u0648\\u0647\\u0627\\u062F \\u0627\\u0644\\u0645\\u0647\\u0645."
t["I can mark the trees all day. I still need an axe to fell them."] = "\\u0641\\u064A\\u0646\\u064A \\u0639\\u0644\\u0651\\u0645 \\u0627\\u0644\\u0634\\u062C\\u0631 \\u0637\\u0648\\u0644 \\u0627\\u0644\\u0646\\u0647\\u0627\\u0631\\u060C \\u0628\\u0633 \\u0644\\u0627\\u0632\\u0645\\u0646\\u064A \\u0641\\u0627\\u0633 \\u0644\\u0648\\u0642\\u0651\\u0639\\u0647."
t["I can miss a zombie at ten paces, but not this tree."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u062E\\u0637\\u064A \\u0632\\u0648\\u0645\\u0628\\u064A \\u0645\\u0646 \\u0639\\u0634\\u0631 \\u062E\\u0637\\u0648\\u0627\\u062A\\u060C \\u0628\\u0633 \\u0645\\u0648 \\u0647\\u0627\\u0644\\u0634\\u062C\\u0631\\u0629."
t["I can push through a lot. Thirst is winning."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u062A\\u062D\\u0645\\u0644 \\u0643\\u062A\\u064A\\u0631. \\u0628\\u0633 \\u0627\\u0644\\u0639\\u0637\\u0634 \\u0639\\u0645 \\u064A\\u0631\\u0628\\u062D."
t["I can scavenge this route. I will avoid containers you already searched."] = "\\u0641\\u064A\\u0646\\u064A \\u0641\\u062A\\u0651\\u0634 \\u0647\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642. \\u0648\\u0645\\u0627 \\u0628\\u0641\\u062A\\u062D \\u0627\\u0644\\u0644\\u064A \\u0641\\u062A\\u0634\\u062A\\u0647 \\u0623\\u0646\\u062A."
t["I can search as we move. I will leave anything you have already claimed alone."] = "\\u0641\\u064A\\u0646\\u064A \\u0641\\u062A\\u0651\\u0634 \\u0648\\u0646\\u062D\\u0646\\u0627 \\u0645\\u0627\\u0634\\u064A\\u064A\\u0646. \\u0648\\u0645\\u0627 \\u0628\\u0642\\u0631\\u0628 \\u0639\\u0627\\u0644\\u0644\\u064A \\u062D\\u062C\\u0632\\u062A\\u0647."
t["I can see that yellow light when you talk about it."] = "\\u0628\\u0634\\u0648\\u0641 \\u0647\\u062F\\u0627\\u0643 \\u0627\\u0644\\u0636\\u0648 \\u0627\\u0644\\u0623\\u0635\\u0641\\u0631 \\u0644\\u0645\\u0627 \\u062A\\u062D\\u0643\\u064A \\u0639\\u0646\\u0647."
t["I can see the steps clearly. No need to rush them."] = "\\u0634\\u0627\\u064A\\u0641\\u0629 \\u0627\\u0644\\u062E\\u0637\\u0648\\u0627\\u062A \\u0645\\u0646\\u064A\\u062D. \\u0645\\u0627 \\u0641\\u064A \\u062F\\u0627\\u0639\\u064A \\u0644\\u0644\\u0639\\u062C\\u0644\\u0629."
t["I can sit a minute. It's good to hear your voice."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0642\\u0639\\u062F \\u062F\\u0642\\u064A\\u0642\\u0629. \\u062D\\u0644\\u0648 \\u0627\\u0633\\u0645\\u0639 \\u0635\\u0648\\u062A\\u0643."
t["I can smell the last three houses on this jacket."] = "\\u0634\\u0627\\u0645\\u0629 \\u0631\\u064A\\u062D\\u0629 \\u0622\\u062E\\u0631 \\u062A\\u0644\\u0627\\u062A \\u0628\\u064A\\u0648\\u062A \\u0639\\u0644\\u0649 \\u0647\\u0627\\u0644\\u062C\\u0627\\u0643\\u064A\\u062A."
t["I can stand over the ground and look useful. That's about it."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0648\\u0642\\u0641 \\u0641\\u0648\\u0642 \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0648\\u0623\\u0639\\u0645\\u0644 \\u062D\\u0627\\u0644\\u064A \\u0645\\u0641\\u064A\\u062F\\u0629. \\u0628\\u0633 \\u0647\\u064A\\u0643."
t["I can still fight - just clear my arms!"] = "\\u0644\\u0633\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0642\\u0627\\u062A\\u0644 - \\u0628\\u0633 \\u062D\\u0631\\u0631 \\u0625\\u064A\\u062F\\u064A\\u064A!"
t["I can still fight this. I can still... can I?"] = "\\u0644\\u0633\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0642\\u0627\\u0648\\u0645. \\u0644\\u0633\\u0627 \\u0628\\u0642\\u062F\\u0631... \\u0628\\u0642\\u062F\\u0631\\u061F"
t["I can still hear you! Keep coming!"] = "\\u0644\\u0633\\u0627 \\u0633\\u0627\\u0645\\u0639\\u062A\\u0643! \\u0643\\u0645\\u0644 \\u062C\\u0627\\u064A!"
t["I can still remember where the good stations were."] = "\\u0644\\u0633\\u0627 \\u0645\\u062A\\u0630\\u0643\\u0631\\u0629 \\u0648\\u064A\\u0646 \\u0643\\u0627\\u0646\\u062A \\u0627\\u0644\\u0645\\u062D\\u0637\\u0627\\u062A \\u0627\\u0644\\u062D\\u0644\\u0648\\u0629."
t["I can still stand. That is about all I can promise."] = "\\u0644\\u0633\\u0627 \\u0648\\u0627\\u0642\\u0641\\u0629 \\u0639\\u0625\\u062C\\u0631\\u064A\\u064A. \\u0647\\u0627\\u062F \\u0643\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0641\\u064A\\u0646\\u064A \\u0648\\u0639\\u062F \\u0641\\u064A\\u0647."
t["I can stop. Can you?"] = "\\u0623\\u0646\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0648\\u0642\\u0641. \\u0625\\u0646\\u062A \\u0641\\u064A\\u0643\\u061F"
t["I can take a few, not the whole doorway. Moving."] = "\\u0628\\u0642\\u062F\\u0631 \\u0639\\u0644\\u0649 \\u0643\\u0627\\u0645 \\u0648\\u0627\\u062D\\u062F\\u060C \\u0645\\u0648 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0628\\u0627\\u0628 \\u0643\\u0644\\u0647. \\u0639\\u0645 \\u0627\\u062A\\u062D\\u0631\\u0643."
t["I can try one run with you. Then I decide."] = "\\u0641\\u064A\\u0646\\u064A \\u062C\\u0631\\u0628 \\u0645\\u0634\\u0648\\u0627\\u0631 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0639\\u0643. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u0642\\u0631\\u0631."
t["I can use that when we get back to work."] = "\\u0628\\u0633\\u062A\\u0641\\u064A\\u062F \\u0645\\u0646\\u0647\\u0627 \\u0644\\u0645\\u0627 \\u0646\\u0631\\u062C\\u0639 \\u0639\\u0627\\u0644\\u0634\\u063A\\u0644."
t["I can wait a little. Water at the next safe stop."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0633\\u062A\\u0646\\u0649 \\u0634\\u0648\\u064A. \\u0645\\u064A \\u0628\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0627\\u0644\\u0622\\u0645\\u0646\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["I can wait, but the shelves will not fill themselves."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0633\\u062A\\u0646\\u0649\\u060C \\u0628\\u0633 \\u0627\\u0644\\u0631\\u0641\\u0648\\u0641 \\u0645\\u0627 \\u0628\\u062A\\u0639\\u0628\\u0651\\u064A \\u062D\\u0627\\u0644\\u0647\\u0627."
t["I can work with that. I think."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u0634\\u062A\\u063A\\u0644 \\u0628\\u0647\\u0627\\u062F. \\u0623\\u0638\\u0646."
t["I can't breathe! Get them OFF!"] = "\\u0645\\u0648 \\u0639\\u0645 \\u0627\\u062A\\u0646\\u0641\\u0633! \\u0634\\u064A\\u0644\\u0646 \\u0639\\u0646\\u064A!"
t["I can't breathe. Is this it? Is this how it starts?"] = "\\u0645\\u0648 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0627\\u062A\\u0646\\u0641\\u0633. \\u0647\\u064A \\u0647\\u064A\\u0643\\u061F \\u0647\\u064A\\u0643 \\u0628\\u062A\\u0628\\u0644\\u0634\\u061F"
t["I can't build much from whole logs. Help me find a saw."] = "\\u0645\\u0627 \\u0628\\u064A\\u0637\\u0644\\u0639 \\u0634\\u064A \\u0645\\u0646 \\u062C\\u0630\\u0648\\u0639 \\u0643\\u0627\\u0645\\u0644\\u0629. \\u0633\\u0627\\u0639\\u062F\\u0646\\u064A \\u0644\\u0627\\u0642\\u064A \\u0645\\u0646\\u0634\\u0627\\u0631."
t["I can't catch my breath, %1."] = "\\u0645\\u0648 \\u0639\\u0645 \\u0628\\u0644\\u062D\\u0642 \\u0646\\u0641\\u0633\\u064A \\u064A\\u0627 %1."
t["I can't clean that fish with my bare hands. Find me a knife."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0646\\u0636\\u0651\\u0641 \\u0627\\u0644\\u0633\\u0645\\u0643\\u0629 \\u0628\\u0625\\u064A\\u062F\\u064A\\u064A. \\u062F\\u0628\\u0631\\u0644\\u064A \\u0633\\u0643\\u064A\\u0646\\u0629."
t["I can't complete that as things stand."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u062E\\u0644\\u0635\\u0647\\u0627 \\u0628\\u0647\\u0627\\u0644\\u0648\\u0636\\u0639."
t["I can't cook a pot meal without the pot."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0639\\u0645\\u0644 \\u0637\\u0628\\u062E\\u0629 \\u0637\\u0646\\u062C\\u0631\\u0629 \\u0628\\u0644\\u0627 \\u0637\\u0646\\u062C\\u0631\\u0629."
t["I can't cook this cold. We need a heat source."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0637\\u0628\\u062E \\u0639\\u0627\\u0644\\u0628\\u0627\\u0631\\u062F. \\u0628\\u062F\\u0646\\u0627 \\u0634\\u064A \\u064A\\u0633\\u062E\\u0651\\u0646."
t["I can't count them all."] = "\\u0645\\u0627 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0639\\u062F\\u0646 \\u0643\\u0644\\u0646."
t["I can't count them anymore. Go!"] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0639\\u062F\\u0646. \\u0631\\u0648\\u062D!"
t["I can't cover anyone from inside that crush."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u063A\\u0637\\u064A \\u062D\\u062F\\u0627 \\u0645\\u0646 \\u062C\\u0648\\u0627 \\u0647\\u0627\\u0644\\u0639\\u062C\\u0642\\u0629."
t["I can't dig without a shovel."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u062D\\u0641\\u0631 \\u0628\\u0644\\u0627 \\u0643\\u0631\\u064A\\u0643."
t["I can't dismantle it without a screwdriver."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0641\\u0643\\u0651\\u0647\\u0627 \\u0628\\u0644\\u0627 \\u0645\\u0641\\u0643."
t["I can't do another argument right now."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A\\u0646\\u064A \\u0639\\u0644\\u0649 \\u062E\\u0646\\u0627\\u0642\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629 \\u0647\\u0644\\u0623."
t["I can't do that safely from here. We need another approach."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0628\\u0623\\u0645\\u0627\\u0646 \\u0645\\u0646 \\u0647\\u0648\\u0646. \\u0628\\u062F\\u0646\\u0627 \\u0637\\u0631\\u064A\\u0642\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["I can't do that safely."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0628\\u0623\\u0645\\u0627\\u0646."
t["I can't do this on an empty body anymore."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A\\u0646\\u064A \\u0643\\u0645\\u0651\\u0644 \\u0648\\u062C\\u0633\\u0645\\u064A \\u0641\\u0627\\u0636\\u064A."
t["I can't do this right now. Please leave me alone."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0647\\u0644\\u0623. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0627\\u062A\\u0631\\u0643\\u0646\\u064A \\u0644\\u062D\\u0627\\u0644\\u064A."
t["I can't feel my hands anymore."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u062D\\u0627\\u0633\\u0629 \\u0628\\u0625\\u064A\\u062F\\u064A\\u064A."
t["I can't fish with my hands. Not these fish, anyway."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0635\\u0637\\u0627\\u062F \\u0628\\u0625\\u064A\\u062F\\u064A\\u064A. \\u0645\\u0648 \\u0647\\u0627\\u0644\\u0633\\u0645\\u0643 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0623\\u0642\\u0644."
t["I can't get my feet under me. I'm backing off."] = "\\u0645\\u0648 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0627\\u062B\\u0628\\u062A \\u0625\\u062C\\u0631\\u064A\\u064A. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["I can't get up - hurry!"] = "\\u0645\\u0627 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0642\\u0648\\u0645 - \\u0628\\u0633\\u0631\\u0639\\u0629!"
t["I can't get up! %1, hurry!"] = "\\u0645\\u0627 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0642\\u0648\\u0645! %1, \\u0628\\u0633\\u0631\\u0639\\u0629!"
t["I can't hear myself think with anyone near me."] = "\\u0645\\u0627 \\u0628\\u0633\\u0645\\u0639 \\u062D\\u0627\\u0644\\u064A \\u0639\\u0645 \\u0641\\u0643\\u0631 \\u0648\\u062D\\u062F\\u0627 \\u0642\\u0631\\u064A\\u0628 \\u0645\\u0646\\u064A."
t["I can't hear the room over my own heartbeat."] = "\\u0645\\u0648 \\u0639\\u0645 \\u0627\\u0633\\u0645\\u0639 \\u0627\\u0644\\u063A\\u0631\\u0641\\u0629 \\u0645\\u0646 \\u062F\\u0642\\u0627\\u062A \\u0642\\u0644\\u0628\\u064A."
t["I can't hide this any longer. One of them bit me."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A\\u0646\\u064A \\u062E\\u0628\\u064A \\u0623\\u0643\\u062A\\u0631. \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0646 \\u0639\\u0636\\u0646\\u064A."
t["I can't hold that approach. Coming back."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0635\\u062F \\u0647\\u0627\\u0644\\u0647\\u062C\\u0648\\u0645. \\u0631\\u0627\\u062C\\u0639\\u0629."
t["I can't hold two! Back!"] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0639\\u0627\\u0644\\u062A\\u0646\\u064A\\u0646! \\u0644\\u0648\\u0631\\u0627!"
t["I can't keep anyone safe while I'm tripping over this."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u062D\\u0645\\u064A \\u062D\\u062F\\u0627 \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u062A\\u0639\\u062A\\u0631 \\u0628\\u0647\\u0627\\u062F."
t["I can't keep carrying everyone else's fear too."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0644 \\u0634\\u064A\\u0644 \\u062E\\u0648\\u0641 \\u0627\\u0644\\u0643\\u0644 \\u0641\\u0648\\u0642 \\u062E\\u0648\\u0641\\u064A."
t["I can't keep fishing without bait."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0643\\u0641\\u0651\\u064A \\u0635\\u064A\\u062F \\u0628\\u0644\\u0627 \\u0637\\u0639\\u0645."
t["I can't keep my eyes open. Please stop."] = "\\u0645\\u0627 \\u0639\\u0645 \\u0628\\u0642\\u062F\\u0631 \\u062E\\u0644\\u064A \\u0639\\u064A\\u0648\\u0646\\u064A \\u0645\\u0641\\u062A\\u062D\\u0629. \\u0648\\u0642\\u0627\\u0641 \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["I can't keep my thoughts in order. I need sleep."] = "\\u0623\\u0641\\u0643\\u0627\\u0631\\u064A \\u0645\\u0648 \\u0639\\u0645 \\u062A\\u062A\\u0631\\u062A\\u0628. \\u0628\\u062F\\u064A \\u0646\\u0627\\u0645."
t["I can't leave you alone in this world. Get me back up!"] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u062A\\u0631\\u0643\\u0643 \\u0644\\u062D\\u0627\\u0644\\u0643 \\u0628\\u0647\\u0627\\u0644\\u062F\\u0646\\u064A\\u0627. \\u0642\\u0648\\u0645\\u0646\\u064A!"
t["I can't leave you alone out here!"] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0627\\u062A\\u0631\\u0643\\u0643 \\u0644\\u062D\\u0627\\u0644\\u0643 \\u0647\\u0648\\u0646!"
t["I can't make myself care what happens next."] = "\\u0645\\u0627 \\u0639\\u0645 \\u0628\\u0642\\u062F\\u0631 \\u064A\\u0647\\u0645\\u0646\\u064A \\u0634\\u0648 \\u0631\\u062D \\u064A\\u0635\\u064A\\u0631 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["I can't make the cut with what I have."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0642\\u0635\\u0651 \\u0628\\u0627\\u0644\\u0644\\u064A \\u0645\\u0639\\u064A."
t["I can't promise a good day. I'll try for the next hour."] = "\\u0645\\u0627 \\u0628\\u0648\\u0639\\u062F \\u0628\\u064A\\u0648\\u0645 \\u062D\\u0644\\u0648. \\u0628\\u062C\\u0631\\u0628 \\u0639\\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["I can't pry this loose with my hands."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u062E\\u0644\\u0639 \\u0647\\u0627\\u062F \\u0628\\u0625\\u064A\\u062F\\u064A\\u064A."
t["I can't pull this apart with my hands."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0641\\u0643\\u0651 \\u0647\\u0627\\u062F \\u0628\\u0625\\u064A\\u062F\\u064A\\u064A."
t["I can't put dinner straight on the burner. Find me a pan."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u062D\\u0637 \\u0627\\u0644\\u0639\\u0634\\u0627 \\u0639\\u0627\\u0644\\u0646\\u0627\\u0631 \\u0645\\u0628\\u0627\\u0634\\u0631\\u0629. \\u062F\\u0628\\u0631\\u0644\\u064A \\u0645\\u0642\\u0644\\u0627\\u064A\\u0629."
t["I can't reach it safely. Clear the approach first."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0648\\u0635\\u0644 \\u0644\\u0639\\u0646\\u062F\\u0647 \\u0628\\u0623\\u0645\\u0627\\u0646. \\u0646\\u0636\\u0641 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0623\\u0648\\u0644."
t["I can't remember the tune. I remember who sang it."] = "\\u0645\\u0648 \\u0645\\u062A\\u0630\\u0643\\u0631\\u0629 \\u0627\\u0644\\u0644\\u062D\\u0646. \\u0645\\u062A\\u0630\\u0643\\u0631\\u0629 \\u0645\\u064A\\u0646 \\u063A\\u0646\\u0627\\u0647."
t["I can't secure this without nails."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u062B\\u0628\\u0651\\u062A \\u0647\\u0627\\u062F \\u0628\\u0644\\u0627 \\u0628\\u0633\\u0627\\u0645\\u064A\\u0631."
t["I can't serve everyone from the same pot."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0637\\u0639\\u0645\\u064A \\u0627\\u0644\\u0643\\u0644 \\u0645\\u0646 \\u0646\\u0641\\u0633 \\u0627\\u0644\\u0637\\u0646\\u062C\\u0631\\u0629."
t["I can't sit still. I can't even think sitting still."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0642\\u0639\\u062F. \\u062D\\u062A\\u0649 \\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0641\\u0643\\u0631 \\u0648\\u0623\\u0646\\u0627 \\u0642\\u0627\\u0639\\u062F\\u0629."
t["I can't start without a usable hammer."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0628\\u0644\\u0634 \\u0628\\u0644\\u0627 \\u0634\\u0627\\u0643\\u0648\\u0634 \\u064A\\u0646\\u0641\\u0639."
t["I can't stop listening for footsteps that aren't ours."] = "\\u0645\\u0627 \\u0628\\u0642\\u062F\\u0631 \\u0648\\u0642\\u0641 \\u0627\\u0633\\u0645\\u0639 \\u062E\\u0637\\u0648\\u0627\\u062A \\u0645\\u0648 \\u062E\\u0637\\u0648\\u0627\\u062A\\u0646\\u0627."
t["I can't swallow. Please, water."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0628\\u0644\\u0639. \\u0645\\u064A\\u060C \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["I can't swing again and still get away."] = "\\u0625\\u0630\\u0627 \\u0636\\u0631\\u0628\\u062A \\u0643\\u0645\\u0627\\u0646 \\u0636\\u0631\\u0628\\u0629 \\u0645\\u0627 \\u0628\\u0644\\u062D\\u0642 \\u0627\\u0647\\u0631\\u0628."
t["I can't take that many at arm's length."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0639\\u0644\\u064A\\u0647\\u0646 \\u0643\\u0644\\u0647\\u0646 \\u0639\\u0645\\u0633\\u0627\\u0641\\u0629 \\u062F\\u0631\\u0627\\u0639."
t["I can't think past how hungry I am."] = "\\u0645\\u0627 \\u0639\\u0645 \\u0628\\u0642\\u062F\\u0631 \\u0641\\u0643\\u0631 \\u0628\\u063A\\u064A\\u0631 \\u062C\\u0648\\u0639\\u064A."
t["I can't trust your aim. Give me room."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0648\\u062B\\u0642 \\u0628\\u062A\\u0635\\u0648\\u064A\\u0628\\u0643. \\u0648\\u0633\\u0639\\u0644\\u064A."
t["I can't watch all those angles and watch you too."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0631\\u0627\\u0642\\u0628 \\u0643\\u0644 \\u0647\\u0627\\u0644\\u062C\\u0647\\u0627\\u062A \\u0648\\u0631\\u0627\\u0642\\u0628\\u0643 \\u0643\\u0645\\u0627\\u0646."
t["I cannot breathe. I cannot breathe."] = "\\u0645\\u0648 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0627\\u062A\\u0646\\u0641\\u0633. \\u0645\\u0648 \\u0639\\u0645 \\u0627\\u0642\\u062F\\u0631 \\u0627\\u062A\\u0646\\u0641\\u0633."
t["I cannot carry this and everybody else's silence."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0634\\u064A\\u0644 \\u0647\\u0627\\u062F \\u0648\\u0633\\u0643\\u0648\\u062A \\u0627\\u0644\\u0643\\u0644 \\u0643\\u0645\\u0627\\u0646."
t["I cannot keep going without water."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0643\\u0645\\u0651\\u0644 \\u0628\\u0644\\u0627 \\u0645\\u064A."
t["I cannot keep moving without a drink much longer."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0643\\u0645\\u0651\\u0644 \\u0643\\u062A\\u064A\\u0631 \\u0628\\u0644\\u0627 \\u0634\\u0631\\u0628\\u0629 \\u0645\\u064A."
t["I cannot keep putting off a meal."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0644 \\u0623\\u062C\\u0651\\u0644 \\u0627\\u0644\\u0623\\u0643\\u0644."
t["I cannot keep this pace much longer."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0636\\u0644 \\u0639\\u0647\\u0627\\u0644\\u0633\\u0631\\u0639\\u0629 \\u0643\\u062A\\u064A\\u0631."
t["I cannot keep watch like this."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u062D\\u0631\\u0633 \\u0648\\u0623\\u0646\\u0627 \\u0647\\u064A\\u0643."
t["I cannot turn this soil by hand."] = "\\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0642\\u0644\\u0628 \\u0647\\u0627\\u0644\\u062A\\u0631\\u0627\\u0628 \\u0628\\u0625\\u064A\\u062F\\u064A."
t["I care about you. That's why the answer is no. We tell them."] = "\\u0628\\u0647\\u0645\\u0646\\u064A \\u0623\\u0645\\u0631\\u0643. \\u0645\\u0634\\u0627\\u0646 \\u0647\\u064A\\u0643 \\u0627\\u0644\\u062C\\u0648\\u0627\\u0628 \\u0644\\u0623. \\u0645\\u0646\\u062E\\u0628\\u0631\\u0647\\u0646."
t["I care too much to keep pretending this feels fine."] = "\\u0642\\u0644\\u0628\\u064A \\u0639\\u0644\\u064A\\u0643\\u0646 \\u0643\\u062A\\u064A\\u0631 \\u0644\\u0623\\u0636\\u0644 \\u0645\\u062B\\u0651\\u0644 \\u0625\\u0646\\u0647 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0631 \\u062A\\u0645\\u0627\\u0645."
t["I carried hope in here and %1 out."] = "\\u062F\\u062E\\u0644\\u062A \\u0628\\u0623\\u0645\\u0644 \\u0648\\u0637\\u0644\\u0639\\u062A \\u0628\\u0640%1."
t["I checked our stores. We need to schedule another supply run."] = "\\u0634\\u0641\\u062A \\u0627\\u0644\\u0645\\u0648\\u0646\\u0629. \\u0644\\u0627\\u0632\\u0645 \\u0646\\u062D\\u062F\\u062F \\u0645\\u0634\\u0648\\u0627\\u0631 \\u062A\\u0627\\u0646\\u064A."
t["I checked the bank. We have room to step back."] = "\\u0634\\u064A\\u0643\\u062A \\u0639\\u0627\\u0644\\u0636\\u0641\\u0629. \\u0641\\u064A \\u0645\\u062D\\u0644 \\u0646\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627."
t["I checked the cover. %1 looks useful enough to carry."] = "\\u0634\\u0641\\u062A \\u0627\\u0644\\u063A\\u0644\\u0627\\u0641. %1 \\u0634\\u0643\\u0644\\u0647 \\u0645\\u0641\\u064A\\u062F \\u0648\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u064A\\u0646\\u062D\\u0645\\u0644."
t["I could almost pretend this is a normal house."] = "\\u0628\\u0643\\u0627\\u062F \\u0627\\u0639\\u0645\\u0644 \\u062D\\u0627\\u0644\\u064A \\u0647\\u0627\\u062F \\u0628\\u064A\\u062A \\u0639\\u0627\\u062F\\u064A."
t["I could close my eyes because I knew you were here."] = "\\u0643\\u0646\\u062A \\u0627\\u0642\\u062F\\u0631 \\u063A\\u0645\\u0636 \\u0639\\u064A\\u0648\\u0646\\u064A \\u0644\\u0623\\u0646\\u064A \\u0639\\u0627\\u0631\\u0641\\u0629 \\u0625\\u0646\\u0643 \\u0647\\u0648\\u0646."
t["I could eat when we get a safe minute."] = "\\u0628\\u0642\\u062F\\u0631 \\u0622\\u0643\\u0644 \\u0644\\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631 \\u0645\\u0639\\u0646\\u0627 \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0623\\u0645\\u0627\\u0646."
t["I could get used to this part."] = "\\u0641\\u064A\\u0646\\u064A \\u0627\\u062A\\u0639\\u0648\\u062F \\u0639\\u0647\\u0627\\u0644\\u0642\\u0633\\u0645."
t["I could really use a cigarette right now."] = "\\u0628\\u0645\\u0648\\u062A \\u0639\\u0644\\u0649 \\u0633\\u064A\\u062C\\u0627\\u0631\\u0629 \\u0647\\u0644\\u0623."
t["I could sleep now without smelling yesterday."] = "\\u0647\\u0644\\u0623 \\u0641\\u064A\\u0646\\u064A \\u0646\\u0627\\u0645 \\u0628\\u0644\\u0627 \\u0631\\u064A\\u062D\\u0629 \\u0645\\u0628\\u0627\\u0631\\u062D."
t["I could use a little space."] = "\\u0628\\u062F\\u064A \\u0634\\u0648\\u064A\\u0629 \\u0645\\u0633\\u0627\\u0641\\u0629."
t["I could use medical help and fresh bandages."] = "\\u0628\\u062F\\u064A \\u0645\\u0633\\u0627\\u0639\\u062F\\u0629 \\u0637\\u0628\\u064A\\u0629 \\u0648\\u0634\\u0627\\u0634 \\u062C\\u062F\\u064A\\u062F."
t["I could use rest when we get a safe chance."] = "\\u0628\\u062F\\u064A \\u0627\\u0631\\u062A\\u0627\\u062D \\u0644\\u0645\\u0627 \\u062A\\u0633\\u0646\\u062D \\u0641\\u0631\\u0635\\u0629 \\u0622\\u0645\\u0646\\u0629."
t["I could use water at the next stop."] = "\\u0628\\u062F\\u064A \\u0645\\u064A \\u0628\\u0627\\u0644\\u0648\\u0642\\u0641\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["I couldn't finish %1. I'll try again in about %2."] = "\\u0645\\u0627 \\u0642\\u062F\\u0631\\u062A \\u062E\\u0644\\u0651\\u0635 %1. \\u0631\\u062D \\u062C\\u0631\\u0628 \\u0643\\u0645\\u0627\\u0646 \\u062D\\u0648\\u0627\\u0644\\u064A %2."
t["I couldn't keep %1 going. I'll retry in %2."] = "\\u0645\\u0627 \\u0642\\u062F\\u0631\\u062A \\u0643\\u0641\\u0651\\u064A %1. \\u0631\\u062D \\u0639\\u064A\\u062F \\u0628\\u0639\\u062F %2."
t["I couldn't outrun a mistake now. I'm resting behind cover."] = "\\u0647\\u0644\\u0623 \\u0645\\u0627 \\u0628\\u0633\\u0628\\u0642 \\u063A\\u0644\\u0637\\u0629 \\u062D\\u062A\\u0649. \\u0631\\u062D \\u0627\\u0631\\u062A\\u0627\\u062D \\u0648\\u0631\\u0627 \\u0633\\u0627\\u062A\\u0631."
t["I count four moving shapes."] = "\\u0639\\u062F\\u064A\\u062A \\u0623\\u0631\\u0628\\u0639 \\u062E\\u064A\\u0627\\u0644\\u0627\\u062A \\u0639\\u0645 \\u062A\\u062A\\u062D\\u0631\\u0643."
t["I count stars when I can't stand counting anything else."] = "\\u0628\\u0639\\u062F\\u0651 \\u0627\\u0644\\u0646\\u062C\\u0648\\u0645 \\u0644\\u0645\\u0627 \\u0645\\u0627 \\u0628\\u0637\\u064A\\u0642 \\u0639\\u062F\\u0651 \\u0634\\u064A \\u062A\\u0627\\u0646\\u064A."
t["I count two. Leave us an exit."] = "\\u0639\\u062F\\u064A\\u062A \\u062A\\u0646\\u064A\\u0646. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062A\\u0631\\u0643 \\u0645\\u062E\\u0631\\u062C."
t["I count us and come up one short. Every time."] = "\\u0628\\u0639\\u062F\\u0651\\u0646\\u0627 \\u0648\\u0628\\u0637\\u0644\\u0639 \\u0648\\u0627\\u062D\\u062F \\u0646\\u0627\\u0642\\u0635. \\u0643\\u0644 \\u0645\\u0631\\u0629."
t["I counted the cans twice and got two different answers."] = "\\u0639\\u062F\\u0651\\u064A\\u062A \\u0627\\u0644\\u0639\\u0644\\u0628 \\u0645\\u0631\\u062A\\u064A\\u0646 \\u0648\\u0637\\u0644\\u0639\\u0644\\u064A \\u062C\\u0648\\u0627\\u0628\\u064A\\u0646 \\u0645\\u062E\\u062A\\u0644\\u0641\\u064A\\u0646."
t["I counted the cans twice and got two different goddamn answers."] = "\\u0639\\u062F\\u0651\\u064A\\u062A \\u0627\\u0644\\u0639\\u0644\\u0628 \\u0645\\u0631\\u062A\\u064A\\u0646 \\u0648\\u0637\\u0644\\u0639\\u0644\\u064A \\u062C\\u0648\\u0627\\u0628\\u064A\\u0646 \\u0645\\u062E\\u062A\\u0644\\u0641\\u064A\\u0646 \\u064A\\u0644\\u0639\\u0646."
t["I counted the doors twice. I'd feel better near one."] = "\\u0639\\u062F\\u064A\\u062A \\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0645\\u0631\\u062A\\u064A\\u0646. \\u0628\\u0631\\u062A\\u0627\\u062D \\u0623\\u0643\\u062A\\u0631 \\u062C\\u0646\\u0628 \\u0648\\u0627\\u062D\\u062F."
t["I counted the exits out here. There aren't any. I counted anyway."] = "\\u0639\\u062F\\u0651\\u064A\\u062A \\u0627\\u0644\\u0645\\u062E\\u0627\\u0631\\u062C \\u0647\\u0648\\u0646. \\u0645\\u0627 \\u0641\\u064A. \\u0648\\u0639\\u062F\\u0651\\u064A\\u062A \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u062D\\u0627\\u0644."
t["I counted us this morning. I count us every morning now."] = "\\u0639\\u062F\\u0651\\u064A\\u062A\\u0646\\u0627 \\u0627\\u0644\\u0635\\u0628\\u062D. \\u0635\\u0631\\u062A \\u0639\\u062F\\u0651\\u0646\\u0627 \\u0643\\u0644 \\u0635\\u0628\\u062D."
t["I didn't agree with every page. That's why it was worth reading."] = "\\u0645\\u0627 \\u0648\\u0627\\u0641\\u0642\\u062A \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u0635\\u0641\\u062D\\u0629. \\u0648\\u0645\\u0634\\u0627\\u0646 \\u0647\\u064A\\u0643 \\u0627\\u0633\\u062A\\u0627\\u0647\\u0644 \\u064A\\u0646\\u0642\\u0631\\u0627."
t["I didn't want the others to hear it first. I've been bitten."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646 \\u064A\\u0633\\u0645\\u0639\\u0648\\u0647\\u0627 \\u0642\\u0628\\u0644\\u0643. \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["I didn't want this fight!"] = "\\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0628\\u062F\\u064A \\u0647\\u0627\\u0644\\u062E\\u0646\\u0627\\u0642\\u0629!"
t["I don't agree with every call, but I trust you to make one."] = "\\u0645\\u0648 \\u0645\\u0648\\u0627\\u0641\\u0642\\u0629 \\u0639\\u0644\\u0649 \\u0643\\u0644 \\u0642\\u0631\\u0627\\u0631\\u060C \\u0628\\u0633 \\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643 \\u062A\\u0627\\u062E\\u062F \\u0642\\u0631\\u0627\\u0631."
t["I don't even have a weapon. No."] = "\\u062D\\u062A\\u0649 \\u0645\\u0627 \\u0645\\u0639\\u064A \\u0633\\u0644\\u0627\\u062D. \\u0644\\u0623."
t["I don't have a clean fight in me. Backing off."] = "\\u0645\\u0627 \\u0639\\u0646\\u062F\\u064A \\u0642\\u062A\\u0627\\u0644 \\u0646\\u0636\\u064A\\u0641. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["I don't have a goal beyond staying useful today."] = "\\u0645\\u0627 \\u0639\\u0646\\u062F\\u064A \\u0647\\u062F\\u0641 \\u063A\\u064A\\u0631 \\u0625\\u0646\\u064A \\u0643\\u0648\\u0646 \\u0645\\u0641\\u064A\\u062F\\u0629 \\u0627\\u0644\\u064A\\u0648\\u0645."
t["I don't have anything left in me today."] = "\\u0645\\u0627 \\u0636\\u0644 \\u0641\\u064A\\u0646\\u064A \\u0634\\u064A \\u0627\\u0644\\u064A\\u0648\\u0645."
t["I don't have room for all of them."] = "\\u0645\\u0627 \\u0639\\u0646\\u062F\\u064A \\u0645\\u062C\\u0627\\u0644 \\u0644\\u0643\\u0644\\u0647\\u0646."
t["I don't hurt anymore. I think that's bad."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0639\\u0645 \\u064A\\u0648\\u062C\\u0639\\u0646\\u064A \\u0634\\u064A. \\u0648\\u0634\\u0643\\u0644\\u0647 \\u0634\\u064A \\u0639\\u0627\\u0637\\u0644."
t["I don't know you well enough to answer that yet."] = "\\u0644\\u0633\\u0627 \\u0645\\u0627 \\u0628\\u0639\\u0631\\u0641\\u0643 \\u0643\\u0641\\u0627\\u064A\\u0629 \\u0644\\u062C\\u0627\\u0648\\u0628 \\u0639\\u0647\\u0627\\u062F."
t["I don't like how much I'd notice you gone."] = "\\u0645\\u0648 \\u0639\\u0627\\u062C\\u0628\\u0646\\u064A \\u0642\\u062F\\u064A\\u0634 \\u0631\\u062D \\u062D\\u0633 \\u0628\\u063A\\u064A\\u0627\\u0628\\u0643."
t["I don't like it, but I understand the reason."] = "\\u0645\\u0648 \\u0639\\u0627\\u062C\\u0628\\u0646\\u064A\\u060C \\u0628\\u0633 \\u0641\\u0627\\u0647\\u0645\\u0629 \\u0627\\u0644\\u0633\\u0628\\u0628."
t["I don't like the odds anymore. Coming back."] = "\\u0645\\u0627 \\u0639\\u0627\\u062F \\u0639\\u062C\\u0628\\u062A\\u0646\\u064A \\u0627\\u0644\\u062D\\u0633\\u0628\\u0629. \\u0631\\u0627\\u062C\\u0639\\u0629."
t["I don't like this fog. Anything could be ten steps away."] = "\\u0645\\u0648 \\u0645\\u0631\\u062A\\u0627\\u062D\\u0629 \\u0644\\u0647\\u0627\\u0644\\u0636\\u0628\\u0627\\u0628. \\u0623\\u064A \\u0634\\u064A \\u0645\\u0645\\u0643\\u0646 \\u064A\\u0643\\u0648\\u0646 \\u0639\\u0628\\u0639\\u062F \\u0639\\u0634\\u0631 \\u062E\\u0637\\u0648\\u0627\\u062A."
t["I don't like this position. We are one surprise away from being trapped."] = "\\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0645\\u0648 \\u0639\\u0627\\u062C\\u0628\\u0646\\u064A. \\u0645\\u0641\\u0627\\u062C\\u0623\\u0629 \\u0648\\u062D\\u062F\\u0629 \\u0648\\u0645\\u0646\\u0639\\u0644\\u0642."
t["I don't mind a fight. I mind three fronts. Backing off."] = "\\u0645\\u0627 \\u0639\\u0646\\u062F\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0645\\u0639 \\u0627\\u0644\\u0642\\u062A\\u0627\\u0644. \\u0645\\u0634\\u0643\\u0644\\u062A\\u064A \\u062A\\u0644\\u0627\\u062A \\u062C\\u0628\\u0647\\u0627\\u062A. \\u0639\\u0645 \\u0627\\u0628\\u0639\\u062F."
t["I don't need a speech from you. I need you to keep being you."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0645\\u0646\\u0643 \\u062E\\u0637\\u0628\\u0629. \\u0628\\u062F\\u064A \\u062A\\u0636\\u0644 \\u0625\\u0646\\u062A."
t["I don't see an exit. We need another plan."] = "\\u0645\\u0648 \\u0634\\u0627\\u064A\\u0641\\u0629 \\u0645\\u062E\\u0631\\u062C. \\u0628\\u062F\\u0646\\u0627 \\u062E\\u0637\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["I don't trust easy. You're making it inconvenient."] = "\\u0623\\u0646\\u0627 \\u0645\\u0627 \\u0628\\u0648\\u062B\\u0642 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629. \\u0648\\u0625\\u0646\\u062A \\u0639\\u0645 \\u062A\\u0639\\u0642\\u062F\\u0644\\u064A \\u0627\\u0644\\u0645\\u0648\\u0636\\u0648\\u0639."
t["I don't trust my hands yet. I'm staying clear."] = "\\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0648\\u0627\\u062B\\u0642\\u0629 \\u0628\\u0625\\u064A\\u062F\\u064A\\u064A. \\u0639\\u0645 \\u0636\\u0644 \\u0628\\u0639\\u064A\\u062F\\u0629."
t["I don't want fear to decide who deserves a place at our table."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u0644\\u062E\\u0648\\u0641 \\u064A\\u0642\\u0631\\u0631 \\u0645\\u064A\\u0646 \\u0628\\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0645\\u062D\\u0644 \\u0639\\u0637\\u0627\\u0648\\u0644\\u062A\\u0646\\u0627."
t["I don't want my last face to be that thing's face."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0622\\u062E\\u0631 \\u0648\\u062C\\u0647 \\u0625\\u0644\\u064A \\u064A\\u0643\\u0648\\u0646 \\u0648\\u062C\\u0647 \\u0647\\u0627\\u0644\\u0634\\u064A."
t["I don't want my temper landing on any of you."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0639\\u0635\\u0628\\u064A\\u062A\\u064A \\u062A\\u0646\\u0632\\u0644 \\u0639\\u0644\\u0649 \\u062D\\u062F\\u0627 \\u0645\\u0646\\u0643\\u0646."
t["I don't want to become a burden. I need a drink now."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0635\\u064A\\u0631 \\u0639\\u0628\\u0621. \\u0628\\u062F\\u064A \\u0627\\u0634\\u0631\\u0628 \\u0647\\u0644\\u0623."
t["I don't want to die! %1, I don't want to die!"] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0645\\u0648\\u062A! %1, \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0645\\u0648\\u062A!"
t["I don't want to fight you. Don't make me."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u062A\\u0642\\u0627\\u062A\\u0644 \\u0645\\u0639\\u0643. \\u0644\\u0627 \\u062A\\u062C\\u0628\\u0631\\u0646\\u064A."
t["I don't want to go. I don't want to go. I don't want to go."] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0631\\u0648\\u062D. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0631\\u0648\\u062D. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0631\\u0648\\u062D."
t["I don't want to leave you like this!"] = "\\u0645\\u0627 \\u0628\\u062F\\u064A \\u0627\\u062A\\u0631\\u0643\\u0643 \\u0647\\u064A\\u0643!"
t["I double-checked my pockets. Then I triple-checked them."] = "\\u062A\\u0623\\u0643\\u062F\\u062A \\u0645\\u0646 \\u062C\\u064A\\u0648\\u0628\\u064A \\u0645\\u0631\\u062A\\u064A\\u0646. \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u062A\\u0644\\u0627\\u062A \\u0645\\u0631\\u0627\\u062A."
t["I dream I'm one of them and it's peaceful. Then I wake up hungry."] = "\\u0628\\u062D\\u0644\\u0645 \\u0625\\u0646\\u064A \\u0645\\u0646\\u0647\\u0645 \\u0648\\u0645\\u0631\\u062A\\u0627\\u062D\\u0629. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u0641\\u064A\\u0642 \\u062C\\u0648\\u0639\\u0627\\u0646\\u0629."
t["I feel a little more like myself."] = "\\u062D\\u0627\\u0633\\u0629 \\u062D\\u0627\\u0644\\u064A \\u0631\\u062C\\u0639\\u062A \\u0634\\u0648\\u064A."
t["I feel better when I know everyone has what they need."] = "\\u0628\\u0631\\u062A\\u0627\\u062D \\u0644\\u0645\\u0627 \\u0627\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0647 \\u0643\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0639\\u0647 \\u0627\\u0644\\u0644\\u064A \\u0628\\u062F\\u0648 \\u064A\\u0627\\u0647."
t["I feel brave. Please let it last."] = "\\u062D\\u0627\\u0633\\u0629 \\u062D\\u0627\\u0644\\u064A \\u0634\\u062C\\u0627\\u0639\\u0629. \\u064A\\u0627 \\u0631\\u0628 \\u062A\\u062F\\u0648\\u0645."
t["I feel good. I am still checking every corner."] = "\\u0645\\u0628\\u0633\\u0648\\u0637\\u0629. \\u0648\\u0644\\u0633\\u0627 \\u0628\\u0641\\u062D\\u0635 \\u0643\\u0644 \\u0632\\u0627\\u0648\\u064A\\u0629."
t["I feel ready. Let's make today count."] = "\\u062D\\u0627\\u0633\\u0629 \\u062D\\u0627\\u0644\\u064A \\u062C\\u0627\\u0647\\u0632\\u0629. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062E\\u0644\\u064A \\u0627\\u0644\\u064A\\u0648\\u0645 \\u064A\\u062D\\u0631\\u0632."
t["I feel sharp today. Give me the difficult job."] = "\\u062D\\u0627\\u0633\\u0629 \\u062D\\u0627\\u0644\\u064A \\u0634\\u0627\\u0637\\u0631\\u0629 \\u0627\\u0644\\u064A\\u0648\\u0645. \\u0639\\u0637\\u064A\\u0646\\u064A \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u0635\\u0639\\u0628\\u0629."
t["I feel sick with hunger. Please find something."] = "\\u062A\\u0639\\u0628\\u0627\\u0646\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062C\\u0648\\u0639 \\u0648\\u062C\\u0627\\u064A\\u062A\\u0646\\u064A \\u0644\\u0639\\u064A\\u0629 \\u0646\\u0641\\u0633. \\u0644\\u0627\\u0642\\u064A \\u0634\\u064A \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643."
t["I felt that tug. Come on."] = "\\u062D\\u0633\\u064A\\u062A \\u0628\\u0627\\u0644\\u0634\\u062F\\u0629. \\u064A\\u0644\\u0627."
t["I finished it, but I won't call myself an expert."] = "\\u062E\\u0644\\u0635\\u062A\\u0647\\u060C \\u0628\\u0633 \\u0645\\u0627 \\u0631\\u062D \\u0642\\u0648\\u0644 \\u0639\\u0646 \\u062D\\u0627\\u0644\\u064A \\u062E\\u0628\\u064A\\u0631\\u0629."
t["I finished it. The next job will tell me whether it helped."] = "\\u062E\\u0644\\u0635\\u062A\\u0647. \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0625\\u0630\\u0627 \\u0641\\u0627\\u062F."
t["I finished the book. Time to let someone else have it."] = "\\u062E\\u0644\\u0635\\u062A \\u0627\\u0644\\u0643\\u062A\\u0627\\u0628. \\u062F\\u0648\\u0631 \\u063A\\u064A\\u0631\\u064A \\u064A\\u0627\\u062E\\u062F\\u0647."
t["I followed the sound. Now I can rest my feet."] = "\\u0644\\u062D\\u0642\\u062A \\u0627\\u0644\\u0635\\u0648\\u062A. \\u0647\\u0644\\u0623 \\u0628\\u0631\\u064A\\u062D \\u0625\\u062C\\u0631\\u064A\\u064A."
t["I followed your call back there. I need to know you understand what it cost us."] = "\\u0645\\u0634\\u064A\\u062A \\u0628\\u0643\\u0644\\u0645\\u062A\\u0643 \\u0647\\u0646\\u064A\\u0643. \\u0628\\u062F\\u064A \\u0627\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0643 \\u0641\\u0627\\u0647\\u0645 \\u0634\\u0648 \\u0643\\u0644\\u0641\\u062A\\u0646\\u0627."
t["I forgot how good water can feel."] = "\\u0646\\u0633\\u064A\\u062A \\u0642\\u062F\\u064A\\u0634 \\u0627\\u0644\\u0645\\u064A \\u062D\\u0644\\u0648\\u0629."
t["I fought a tin can and won."] = "\\u062A\\u0642\\u0627\\u062A\\u0644\\u062A \\u0645\\u0639 \\u0639\\u0644\\u0628\\u0629 \\u062A\\u0646\\u0643 \\u0648\\u0631\\u0628\\u062D\\u062A."
t["I found %1! Someone's going to need this."] = "\\u0644\\u0642\\u064A\\u062A %1! \\u0641\\u064A \\u062D\\u062F\\u0627 \\u0631\\u062D \\u064A\\u0644\\u0632\\u0645\\u0647 \\u0647\\u0627\\u0644\\u0634\\u064A."
t["I found %1. Eww, I got some of it on my hands."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0625\\u064A\\u0639, \\u0625\\u062C\\u0627\\u0646\\u064A \\u0645\\u0646\\u0647 \\u0639\\u0625\\u064A\\u062F\\u064A."
t["I found %1. Remind me to pass it on when I'm finished."] = "\\u0644\\u0642\\u064A\\u062A %1. \\u0630\\u0643\\u0631\\u0646\\u064A \\u0627\\u0639\\u0637\\u064A\\u0647 \\u0644\\u062D\\u062F\\u0627 \\u0644\\u0645\\u0627 \\u062E\\u0644\\u0635."
t["I found a blue cup in the cupboard. Kept it for no reason."] = "\\u0644\\u0642\\u064A\\u062A \\u0641\\u0646\\u062C\\u0627\\u0646 \\u0623\\u0632\\u0631\\u0642 \\u0628\\u0627\\u0644\\u062E\\u0632\\u0627\\u0646\\u0629. \\u062E\\u0644\\u064A\\u062A\\u0647 \\u0628\\u0644\\u0627 \\u0633\\u0628\\u0628."
t["I found a family with you. Don't let them take it away!"] = "\\u0644\\u0642\\u064A\\u062A \\u0639\\u064A\\u0644\\u0629 \\u0645\\u0639\\u0643. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0647\\u0646 \\u064A\\u0627\\u062E\\u062F\\u0648\\u0647\\u0627!"
t["I found a good page today, %1. Want to hear it in my own words?"] = "\\u0644\\u0642\\u064A\\u062A \\u0635\\u0641\\u062D\\u0629 \\u062D\\u0644\\u0648\\u0629 \\u0627\\u0644\\u064A\\u0648\\u0645 \\u064A\\u0627 %1. \\u0628\\u062F\\u0643 \\u0627\\u062D\\u0643\\u064A\\u0644\\u0643 \\u064A\\u0627\\u0647\\u0627 \\u0628\\u0643\\u0644\\u0627\\u0645\\u064A\\u061F"
t["I found a useful claim. Help me find the hole in it, %1."] = "\\u0644\\u0642\\u064A\\u062A \\u0645\\u0639\\u0644\\u0648\\u0645\\u0629 \\u0645\\u0641\\u064A\\u062F\\u0629. \\u0633\\u0627\\u0639\\u062F\\u0646\\u064A \\u0644\\u0627\\u0642\\u064A \\u0627\\u0644\\u063A\\u0644\\u0637 \\u0641\\u064A\\u0647\\u0627 \\u064A\\u0627 %1."
t["I found one of Milli's teabags. She says it has one more cup in it."] = "\\u0644\\u0642\\u064A\\u062A \\u0643\\u064A\\u0633 \\u0634\\u0627\\u064A \\u0644\\u0645\\u064A\\u0644\\u064A. \\u0628\\u062A\\u0642\\u0648\\u0644 \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0647 \\u0643\\u0627\\u0633\\u0629."
t["I found one useful point. I'll keep reading for the second."] = "\\u0644\\u0642\\u064A\\u062A \\u0646\\u0642\\u0637\\u0629 \\u0645\\u0641\\u064A\\u062F\\u0629. \\u0628\\u0643\\u0645\\u0644 \\u0644\\u0623\\u0648\\u0635\\u0644 \\u0644\\u0644\\u062A\\u0627\\u0646\\u064A\\u0629."
t["I found something I wanted you to have."] = "\\u0644\\u0642\\u064A\\u062A \\u0634\\u064A \\u0643\\u0627\\u0646 \\u0628\\u062F\\u064A \\u064A\\u0627\\u0647 \\u064A\\u0643\\u0648\\u0646 \\u0625\\u0644\\u0643."
t["I found the bank. I haven't found a rod."] = "\\u0644\\u0642\\u064A\\u062A \\u0627\\u0644\\u0646\\u0647\\u0631. \\u0627\\u0644\\u0635\\u0646\\u0627\\u0631\\u0629 \\u0644\\u0623."
t["I found the cleaner. Might as well use it."] = "\\u0644\\u0642\\u064A\\u062A \\u0627\\u0644\\u0645\\u0646\\u0638\\u0641. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0633\\u062A\\u0639\\u0645\\u0644\\u0647."
t["I found the wires. They didn't like me."] = "\\u0644\\u0642\\u064A\\u062A \\u0627\\u0644\\u0634\\u0631\\u0627\\u064A\\u0637. \\u0628\\u0633 \\u0645\\u0627 \\u062D\\u0628\\u0651\\u0648\\u0646\\u064A."
t["I gave it a fair try. My people need me here."] = "\\u062C\\u0631\\u0628\\u062A\\u0647\\u0627 \\u0628\\u0625\\u0646\\u0635\\u0627\\u0641. \\u0648\\u062C\\u0645\\u0627\\u0639\\u062A\\u064A \\u0645\\u062D\\u062A\\u0627\\u062C\\u064A\\u0646\\u064A \\u0647\\u0648\\u0646."
t["I gave you a chance. No more warnings."] = "\\u0639\\u0637\\u064A\\u062A\\u0643 \\u0641\\u0631\\u0635\\u0629. \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0641\\u064A \\u062A\\u062D\\u0630\\u064A\\u0631\\u0627\\u062A."
t["I gave you every chance to stop!"] = "\\u0639\\u0637\\u064A\\u062A\\u0643 \\u0643\\u0644 \\u0641\\u0631\\u0635\\u0629 \\u062A\\u0648\\u0642\\u0641!"
t["I gave you room to live. You came after me."] = "\\u0639\\u0637\\u064A\\u062A\\u0643 \\u0645\\u062C\\u0627\\u0644 \\u062A\\u0639\\u064A\\u0634. \\u0644\\u062D\\u0642\\u062A\\u0646\\u064A."
t["I got %1! Still useful, still ours."] = "\\u0644\\u0642\\u064A\\u062A %1! \\u0644\\u0633\\u0627 \\u0628\\u064A\\u0641\\u064A\\u062F, \\u0648\\u0644\\u0633\\u0627 \\u0625\\u0644\\u0646\\u0627."
