t["I keep expecting %1 to answer when someone calls out."] = "\\u0643\\u0644 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0646\\u0627\\u062F\\u064A\\u060C \\u0628\\u0633\\u062A\\u0646\\u0649 \\u0627\\u0633\\u0645\\u0639 \\u0635\\u0648\\u062A %1."
t["I keep expecting to hear a bus."] = "\\u0644\\u0633\\u0627 \\u0628\\u062A\\u0648\\u0642\\u0639 \\u0627\\u0633\\u0645\\u0639 \\u0635\\u0648\\u062A \\u0628\\u0627\\u0635."
t["I keep expecting to see %1 walk through that door."] = "\\u0644\\u0633\\u0627 \\u0628\\u0637\\u0644\\u0651\\u0639 \\u0639\\u0627\\u0644\\u0628\\u0627\\u0628 \\u0648\\u0628\\u0633\\u062A\\u0646\\u0649 \\u0634\\u0648\\u0641 %1."
t["I keep folding clothes for people who aren't coming back."] = "\\u0628\\u0636\\u0644 \\u0627\\u0637\\u0648\\u064A \\u062A\\u064A\\u0627\\u0628 \\u0644\\u0646\\u0627\\u0633 \\u0645\\u0648 \\u0631\\u0627\\u062C\\u0639\\u064A\\u0646."
t["I keep forgetting what ordinary conversation sounds like. Help me out, %1."] = "\\u0639\\u0645 \\u0627\\u0646\\u0633\\u0649 \\u0643\\u064A\\u0641 \\u0628\\u064A\\u0643\\u0648\\u0646 \\u0627\\u0644\\u062D\\u0643\\u064A \\u0627\\u0644\\u0639\\u0627\\u062F\\u064A. \\u0633\\u0627\\u0639\\u062F\\u0646\\u064A \\u064A\\u0627 %1."
t["I keep forgetting where I am. Then I remember, and it's worse."] = "\\u0639\\u0645 \\u0627\\u0646\\u0633\\u0649 \\u0648\\u064A\\u0646 \\u0623\\u0646\\u0627. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u062A\\u0630\\u0643\\u0631\\u060C \\u0648\\u0628\\u064A\\u0635\\u064A\\u0631 \\u0623\\u0639\\u0637\\u0644."
t["I keep getting tangled up. Give me clear ground."] = "\\u0639\\u0645 \\u0636\\u0644 \\u0627\\u062A\\u0634\\u0631\\u0628\\u0643. \\u0628\\u062F\\u064A \\u0623\\u0631\\u0636 \\u0646\\u0636\\u064A\\u0641\\u0629."
t["I keep hearing knocking that isn't there. Isn't it?"] = "\\u0628\\u0636\\u0644 \\u0627\\u0633\\u0645\\u0639 \\u062F\\u0642 \\u0645\\u0648 \\u0645\\u0648\\u062C\\u0648\\u062F. \\u0645\\u0648 \\u0645\\u0648\\u062C\\u0648\\u062F\\u061F"
t["I keep imagining a garden party here. With tablecloths."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u062D\\u0641\\u0644\\u0629 \\u0628\\u0627\\u0644\\u062C\\u0646\\u064A\\u0646\\u0629 \\u0647\\u0648\\u0646. \\u0645\\u0639 \\u0634\\u0631\\u0627\\u0634\\u0641."
t["I keep imagining a home inspector walking through here."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0645\\u0641\\u062A\\u0634 \\u0628\\u064A\\u0648\\u062A \\u0639\\u0645 \\u064A\\u062A\\u0645\\u0634\\u0649 \\u0647\\u0648\\u0646."
t["I keep imagining burying each of you. Then I stop. Then I don't."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0625\\u0646\\u064A \\u0639\\u0645 \\u0627\\u062F\\u0641\\u0646 \\u0643\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0641\\u064A\\u0643\\u0646. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u0648\\u0642\\u0641. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0645\\u0627 \\u0628\\u0648\\u0642\\u0641."
t["I keep imagining fresh bread on this table. That smell, you know?"] = "\\u0639\\u0645 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u062E\\u0628\\u0632 \\u0637\\u0627\\u0632\\u0629 \\u0639\\u0644\\u0649 \\u0647\\u0627\\u0644\\u0637\\u0627\\u0648\\u0644\\u0629. \\u0647\\u062F\\u064A\\u0643 \\u0627\\u0644\\u0631\\u064A\\u062D\\u0629\\u060C \\u0628\\u062A\\u0639\\u0631\\u0641\\u061F"
t["I keep inventorying things that aren't ours yet."] = "\\u0628\\u0636\\u0644 \\u0627\\u0639\\u0645\\u0644 \\u062C\\u0631\\u062F \\u0644\\u0634\\u063A\\u0644\\u0627\\u062A \\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0625\\u0644\\u0646\\u0627."
t["I keep picturing a diner reopening. Pie and everything."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0645\\u0637\\u0639\\u0645 \\u0639\\u0645 \\u064A\\u0641\\u062A\\u062D \\u0645\\u0646 \\u062C\\u062F\\u064A\\u062F. \\u0641\\u0637\\u064A\\u0631\\u0629 \\u0648\\u0643\\u0644 \\u0634\\u064A."
t["I keep picturing my own body by a road. Badly dressed."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u062C\\u062B\\u062A\\u064A \\u062C\\u0646\\u0628 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642. \\u0644\\u0627\\u0628\\u0633\\u0629 \\u0634\\u064A \\u0628\\u0634\\u0639."
t["I keep picturing one of them doing its taxes. It fits, somehow."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0645 \\u0639\\u0645 \\u064A\\u0639\\u0628\\u064A \\u0636\\u0631\\u0627\\u064A\\u0628\\u0647. \\u0644\\u0627\\u064A\\u0642\\u0629 \\u0639\\u0644\\u064A\\u0647\\u0645 \\u0628\\u0637\\u0631\\u064A\\u0642\\u0629 \\u0645\\u0627."
t["I keep picturing shoving you at them. Then who'd carry the damn beans."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0625\\u0646\\u064A \\u0639\\u0645 \\u0627\\u062F\\u0641\\u0634\\u0643 \\u0639\\u0644\\u064A\\u0647\\u0645. \\u0628\\u0633 \\u0645\\u064A\\u0646 \\u0628\\u064A\\u062D\\u0645\\u0644 \\u0627\\u0644\\u0641\\u0627\\u0635\\u0648\\u0644\\u064A\\u0627 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646\\u0629."
t["I keep picturing shoving you into a crowd of them. Then who'd carry the beans."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0625\\u0646\\u064A \\u0639\\u0645 \\u0627\\u062F\\u0641\\u0634\\u0643 \\u0644\\u0639\\u0646\\u062F\\u0647\\u0645. \\u0628\\u0633 \\u0645\\u064A\\u0646 \\u0628\\u064A\\u062D\\u0645\\u0644 \\u0627\\u0644\\u0641\\u0627\\u0635\\u0648\\u0644\\u064A\\u0627."
t["I keep picturing the last lesson on the board. Something about the future."] = "\\u0644\\u0633\\u0627 \\u0628\\u062A\\u062E\\u064A\\u0644 \\u0622\\u062E\\u0631 \\u062F\\u0631\\u0633 \\u0639\\u0627\\u0644\\u0644\\u0648\\u062D. \\u0634\\u064A \\u0639\\u0646 \\u0627\\u0644\\u0645\\u0633\\u062A\\u0642\\u0628\\u0644."
t["I keep picturing the walls failing at three in the morning. Exactly three."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646 \\u0639\\u0645 \\u062A\\u0646\\u0647\\u0627\\u0631 \\u0627\\u0644\\u0633\\u0627\\u0639\\u0629 \\u062A\\u0644\\u0627\\u062A\\u0629 \\u0627\\u0644\\u0641\\u062C\\u0631. \\u062A\\u0644\\u0627\\u062A\\u0629 \\u0628\\u0627\\u0644\\u0632\\u0628\\u0637."
t["I keep picturing the worst version of every corner."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0623\\u0633\\u0648\\u0623 \\u0646\\u0633\\u062E\\u0629 \\u0645\\u0646 \\u0643\\u0644 \\u0632\\u0627\\u0648\\u064A\\u0629."
t["I keep picturing this place from the outside. Not comforting."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u062E\\u064A\\u0644 \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0645\\u0646 \\u0628\\u0631\\u0627. \\u0645\\u0648 \\u0645\\u0637\\u0645\\u0651\\u0646."
t["I keep planning raids on places we don't need to raid."] = "\\u0628\\u0636\\u0644 \\u062E\\u0637\\u0637 \\u0644\\u063A\\u0627\\u0631\\u0627\\u062A \\u0639\\u0644\\u0649 \\u0645\\u062D\\u0644\\u0627\\u062A \\u0645\\u0627 \\u0628\\u062F\\u0646\\u0627 \\u0646\\u063A\\u064A\\u0631 \\u0639\\u0644\\u064A\\u0647\\u0627."
t["I keep planning who I'd save first. I hate that I know."] = "\\u0628\\u0636\\u0644 \\u062E\\u0637\\u0637 \\u0645\\u064A\\u0646 \\u0628\\u0646\\u0642\\u0630 \\u0623\\u0648\\u0644. \\u0628\\u0643\\u0631\\u0647 \\u0625\\u0646\\u064A \\u0628\\u0639\\u0631\\u0641."
t["I keep rehearsing an argument from 1989. I was right, dammit."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u0645\\u0631\\u0646 \\u0639\\u0644\\u0649 \\u062E\\u0646\\u0627\\u0642\\u0629 \\u0645\\u0646 1989. \\u0643\\u0627\\u0646 \\u0627\\u0644\\u062D\\u0642 \\u0645\\u0639\\u064A \\u064A\\u0644\\u0639\\u0646."
t["I keep rehearsing an argument from 1989. I was right."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u0645\\u0631\\u0646 \\u0639\\u0644\\u0649 \\u062E\\u0646\\u0627\\u0642\\u0629 \\u0645\\u0646 1989. \\u0643\\u0627\\u0646 \\u0627\\u0644\\u062D\\u0642 \\u0645\\u0639\\u064A."
t["I keep rehearsing my last words. Mostly they're just oh, shit."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u0645\\u0631\\u0646 \\u0639\\u0644\\u0649 \\u0622\\u062E\\u0631 \\u0643\\u0644\\u0645\\u0627\\u062A\\u064A. \\u0623\\u063A\\u0644\\u0628\\u0647\\u0627 \\u0628\\u0633: \\u064A\\u0627 \\u0632\\u0641\\u062A."
t["I keep rehearsing my last words. They're never good enough."] = "\\u0628\\u0636\\u0644 \\u0627\\u062A\\u0645\\u0631\\u0646 \\u0639\\u0644\\u0649 \\u0622\\u062E\\u0631 \\u0643\\u0644\\u0645\\u0627\\u062A\\u064A. \\u0639\\u0645\\u0631\\u0647\\u0627 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u062A \\u0643\\u0641\\u0627\\u064A\\u0629."
t["I keep saving them a seat. Then I remember."] = "\\u0628\\u0636\\u0644 \\u0627\\u062D\\u062C\\u0632\\u0644\\u0647\\u0645 \\u0643\\u0631\\u0633\\u064A. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0628\\u062A\\u0630\\u0643\\u0631."
t["I keep seeing every way that could have gone worse."] = "\\u0644\\u0633\\u0627 \\u0628\\u0634\\u0648\\u0641 \\u0643\\u0644 \\u0637\\u0631\\u064A\\u0642\\u0629 \\u0643\\u0627\\u0646 \\u0645\\u0645\\u0643\\u0646 \\u062A\\u062E\\u0631\\u0628 \\u0641\\u064A\\u0647\\u0627 \\u0623\\u0643\\u062A\\u0631."
t["I keep seeing weak points in the base. I want to fix them."] = "\\u0639\\u0645 \\u0636\\u0644 \\u0634\\u0648\\u0641 \\u0646\\u0642\\u0627\\u0637 \\u0636\\u0639\\u0641 \\u0628\\u0627\\u0644\\u0642\\u0627\\u0639\\u062F\\u0629. \\u0628\\u062F\\u064A \\u0635\\u0644\\u062D\\u0647\\u0627."
t["I keep thinking about church potlucks. Every casserole. Every one."] = "\\u0628\\u0636\\u0644 \\u0641\\u0643\\u0631 \\u0628\\u0639\\u0632\\u0627\\u064A\\u0645 \\u0627\\u0644\\u0643\\u0646\\u064A\\u0633\\u0629. \\u0643\\u0644 \\u0637\\u0628\\u062E\\u0629. \\u0643\\u0644 \\u0648\\u062D\\u062F\\u0629."
t["I keep thinking about their last meal here. Whoever they were."] = "\\u0628\\u0636\\u0644 \\u0641\\u0643\\u0631 \\u0628\\u0622\\u062E\\u0631 \\u0623\\u0643\\u0644\\u0629 \\u0623\\u0643\\u0644\\u0648\\u0647\\u0627 \\u0647\\u0648\\u0646. \\u0645\\u064A\\u0646 \\u0645\\u0627 \\u0643\\u0627\\u0646\\u0648\\u0627."
t["I keep thinking the next fight will be the good story."] = "\\u0628\\u0636\\u0644 \\u0641\\u0643\\u0631 \\u0625\\u0646 \\u0627\\u0644\\u0645\\u0639\\u0631\\u0643\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0631\\u062D \\u062A\\u0643\\u0648\\u0646 \\u0627\\u0644\\u0642\\u0635\\u0629 \\u0627\\u0644\\u062D\\u0644\\u0648\\u0629."
t["I keep thinking the night has more of them in it."] = "\\u0628\\u0636\\u0644 \\u062D\\u0633 \\u0625\\u0646 \\u0627\\u0644\\u0644\\u064A\\u0644 \\u0641\\u064A\\u0647 \\u0645\\u0646\\u0647\\u0645 \\u0623\\u0643\\u062A\\u0631."
t["I keep thinking the radio will play real music again."] = "\\u0628\\u0636\\u0644 \\u0641\\u0643\\u0631 \\u0625\\u0646 \\u0627\\u0644\\u0631\\u0627\\u062F\\u064A\\u0648 \\u0631\\u062D \\u064A\\u0631\\u062C\\u0639 \\u064A\\u062D\\u0637 \\u0645\\u0648\\u0633\\u064A\\u0642\\u0649 \\u0639\\u0646 \\u062C\\u062F."
t["I keep thinking there was something else I could have done for %1."] = "\\u0644\\u0633\\u0627 \\u0628\\u0641\\u0643\\u0631 \\u0625\\u0646\\u0647 \\u0643\\u0627\\u0646 \\u0641\\u064A \\u0634\\u064A \\u062A\\u0627\\u0646\\u064A \\u0641\\u064A\\u0646\\u064A \\u0627\\u0639\\u0645\\u0644\\u0647 \\u0644\\u0640%1."
t["I keep thinking this chair was somebody's favourite."] = "\\u0628\\u0636\\u0644 \\u0641\\u0643\\u0631 \\u0625\\u0646 \\u0647\\u0627\\u0644\\u0643\\u0631\\u0633\\u064A \\u0643\\u0627\\u0646 \\u0627\\u0644\\u0645\\u0641\\u0636\\u0644 \\u0639\\u0646\\u062F \\u062D\\u062F\\u0627."
t["I keep thinking we left someone behind. Count us again."] = "\\u0628\\u0636\\u0644 \\u062D\\u0633 \\u0625\\u0646\\u0627 \\u062A\\u0631\\u0643\\u0646\\u0627 \\u062D\\u062F\\u0627 \\u0648\\u0631\\u0627\\u0646\\u0627. \\u0639\\u062F\\u0651\\u0646\\u0627 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["I keep trying to remember the last ordinary Sunday."] = "\\u0639\\u0645 \\u062D\\u0627\\u0648\\u0644 \\u0627\\u062A\\u0630\\u0643\\u0631 \\u0622\\u062E\\u0631 \\u064A\\u0648\\u0645 \\u0623\\u062D\\u062F \\u0639\\u0627\\u062F\\u064A."
